  ('DECISION_TOPIC_CODE','PRESCRIBED_DRUG_INGREDIENT_REPRESENTATION'),
  ('DECISION_TOPIC_CODE','PO_DURATION_CLINICAL_SIGNIFICANCE'),
  ('DECISION_TOPIC_CODE','CATO_SSN_PATIENT_IDENTIFIER_SEMANTICS'),
