  ('METRIC_TYPE','CANDIDATE'), ('METRIC_TYPE','ACCEPTED'), ('METRIC_TYPE','QUARANTINED'),
  ('METRIC_TYPE','WARNING'), ('METRIC_TYPE','ERROR'),
