select 'c174469b-e3e8-5b7c-968b-42f6664d1e97'::uuid, '8d088953-0f9c-5795-a365-f4b41ba6a493'::uuid, g.release_gate_definition_id,
       c.artifact_id, pg_catalog.decode('3c7e551109ab814712c3b7bbbbbda4d41b457327452e4eee7746e698283fdc46', 'hex'), vr.validation_ruleset_id, '3ae41c2c-f828-5a3c-87a7-ab1eb6af60f0'::uuid,
       (select reference_value_id from pg_temp.bl001_ref where domain_code='RELEASE_GATE_OUTCOME' and value_code='PASSED' and version_number=1),
       '2026-09-24T21:08:29Z'::timestamptz, '2026-09-24T21:08:29Z'::timestamptz, c.principal_id, null, null,
       '30a89c8a-13ff-53e0-849d-202ecf14df4b'::uuid,
       'BL-001 passed all four blocking requirements with 292 accepted and one preserved quarantine.',
