values ('2f38a2d0-6b68-5c73-b529-d0c3aa72fcfe'::uuid, '30a89c8a-13ff-53e0-849d-202ecf14df4b'::uuid,
        (select reference_value_id from pg_temp.bl001_ref where domain_code='EVIDENCE_ROLE' and value_code='RELEASE' and version_number=1),
        'c174469b-e3e8-5b7c-968b-42f6664d1e97'::uuid, 'BL-001 BASELINE_IMPORT/v1 release evaluation.', '2026-09-24T21:08:29Z'::timestamptz);

set constraints all immediate;

-- Stage 11: ACTIVE is appended only after the current release gate is verifiably PASSED.
do $bl001_release_check$
begin
  if not exists (
    select 1 from s2t_fhir.current_release_gate_evaluation e
    join s2t_fhir.reference_value o on o.reference_value_id=e.gate_outcome_value_id
    where e.baseline_version_id='8d088953-0f9c-5795-a365-f4b41ba6a493'::uuid and o.value_code='PASSED'
      and e.release_gate_evaluation_id='c174469b-e3e8-5b7c-968b-42f6664d1e97'::uuid
  ) then raise exception 'BL-001 current release gate is not PASSED; ACTIVE lifecycle event is prohibited'; end if;
  if (select count(*) from s2t_fhir.release_gate_result r join s2t_fhir.reference_value o on o.reference_value_id=r.requirement_outcome_value_id where r.release_gate_evaluation_id='c174469b-e3e8-5b7c-968b-42f6664d1e97'::uuid and o.value_code='PASSED') <> 4 then
    raise exception 'BL-001 release gate does not have four passed requirement results';
  end if;
end
$bl001_release_check$;

   actor_principal_id, initiating_human_principal_id, governance_action_id, reason, supersedes_event_id)
