  ('d717360f-3b6b-5b2c-a368-1b23ecbdecb7'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='ELEMENT_MAPPING' and version_number=1), 'S2T MedicationRequestCato', 72, 'A72:Q72', 'baseline-import', 'v1', '{"cells":{"A":{"header":"Source System","original":"CATO","raw_lexical":"94","type":"string","value":"CATO"},"B":{"header":"Interface Type","original":"XML","raw_lexical":"396","type":"string","value":"XML"},"C":{"header":"Interface Name","original":" CATO Therapy Export","raw_lexical":"113","type":"string","value":" CATO Therapy Export"},"D":{"header":"Field / Expression","original":"/Therapy/Cycles/Therapy:Cycle/Items/Therapy:Medication/PrescribedDrugs/PrescribedDrug/ActiveSubstanceInfo/@UID","raw_lexical":"883","type":"string","value":"/Therapy/Cycles/Therapy:Cycle/Items/Therapy:Medication/PrescribedDrugs/PrescribedDrug/ActiveSubstanceInfo/@UID"},"E":{"header":"Profile where element is defined","original":"LOCAL","raw_lexical":"123","type":"string","value":"LOCAL"},"F":{"header":"Fixed Value","original":null,"raw_lexical":null,"type":"blank","value":null},"G":{"header":"Transformation \nRules","original":"בצע Lookup של ActiveSubstanceInfo/@UID מתוך CATO XML מול DRUGS.Cato_Code בקמיליון.\nכאשר נמצאה התאמה יחידה ותקפה, השתמש ברשומת DRUGS המתאימה לצורך הפעלת מנגנון ההמרה הקיים של קמיליון ל־SNOMED CT.\nקוד ה־SNOMED שהוחזר ממנגנון זה ימופה ל־medicationCodeableConcept.coding[snomed].code.\nאם לא נמצאה התאמה ב־DRUGS.Cato_Code, נמצאו מספר התאמות, או שלא קיים מיפוי SNOMED עבור הרשומה בקמיליון – אין ליצור coding[snomed].\nאין לבצע התאמה על בסיס שם התרופה או דמיון טקסטואלי.","raw_lexical":"968","type":"string","value":"בצע Lookup של ActiveSubstanceInfo/@UID מתוך CATO XML מול DRUGS.Cato_Code בקמיליון.\nכאשר נמצאה התאמה יחידה ותקפה, השתמש ברשומת DRUGS המתאימה לצורך הפעלת מנגנון ההמרה הקיים של קמיליון ל־SNOMED CT.\nקוד ה־SNOMED שהוחזר ממנגנון זה ימופה ל־medicationCodeableConcept.coding[snomed].code.\nאם לא נמצאה התאמה ב־DRUGS.Cato_Code, נמצאו מספר התאמות, או שלא קיים מיפוי SNOMED עבור הרשומה בקמיליון – אין ליצור coding[snomed].\nאין לבצע התאמה על בסיס שם התרופה או דמיון טקסטואלי."},"H":{"header":"Source Business\nDefinition","original":"קוד SNOMED CT של החומר הפעיל, המתקבל באמצעות התאמת ActiveSubstanceInfo/@UID ל־DRUGS.Cato_Code\n והפעלת מנגנון ההמרה הקיים של קטלוג התרופות בקמיליון.","raw_lexical":"987","type":"string","value":"קוד SNOMED CT של החומר הפעיל, המתקבל באמצעות התאמת ActiveSubstanceInfo/@UID ל־DRUGS.Cato_Code\n והפעלת מנגנון ההמרה הקיים של קטלוג התרופות בקמיליון."},"I":{"header":"Target Element name (FHIR)","original":"medicationCodeableConcept.coding[snomed].code","raw_lexical":"199","type":"string","value":"medicationCodeableConcept.coding[snomed].code"},"J":{"header":"Cardinality","original":"0..1","raw_lexical":"78","type":"string","value":"0..1"},"K":{"header":"Bindings to ValueSet","original":null,"raw_lexical":null,"type":"blank","value":null},"L":{"header":"Mandated code system","original":null,"raw_lexical":null,"type":"blank","value":null},"M":{"header":"Irrelevant under s2t","original":null,"raw_lexical":null,"type":"blank","value":null},"N":{"header":"Example","original":null,"raw_lexical":null,"type":"blank","value":null},"O":{"header":"Exceptions handling","original":null,"raw_lexical":null,"type":"blank","value":null},"P":{"header":"Notes","original":null,"raw_lexical":null,"type":"blank","value":null},"Q":{"header":"Decision Status","original":"FINAL","raw_lexical":"659","type":"string","value":"FINAL"}},"range":"A72:Q72","row":72,"schema":"baseline-import-v1","sheet":"S2T MedicationRequestCato"}'::jsonb, pg_catalog.decode('a9137976206dc93a27de36399575c91a1a958e581d27c93676e5f875dbd61f01', 'hex'), 'v1', 'v1', (select reference_value_id from pg_temp.bl001_ref where domain_code='CANDIDATE_DISPOSITION' and value_code='ACCEPTED' and version_number=1), 'me:v1:2a2fda3dc9a68e616feb2c5072bbdfaf3bd80f8e062bc6a474e04294a4f