  ('5c53223d-30b4-5fc3-bdf6-7ef3726fe74e'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='ELEMENT_MAPPING' and version_number=1), 'S2T MedicationRequestCato', 236, 'A236:Q236', 'baseline-import', 'v1', '{"cells":{"A":{"header":"Source System","original":"CATO ","raw_lexical":"347","type":"string","value":"CATO "},"B":{"header":"Interface Type","original":"XML","raw_lexical":"396","type":"string","value":"XML"},"C":{"header":"Interface Name","original":"CATO Therapy Export","raw_lexical":"243","type":"string","value":"CATO Therapy Export"},"D":{"header":"Field / Expression","original":"Therapy:Cycle/Name","raw_lexical":"751","type":"string","value":"Therapy:Cycle/Name"},"E":{"header":"Profile where element is defined","original":"Ext: Medication Regimen HDP","raw_lexical":"399","type":"string","value":"Ext: Medication Regimen HDP"},"F":{"header":"Fixed Value","original":null,"raw_lexical":null,"type":"blank","value":null},"G":{"header":"Transformation \nRules","original":"יש לזהות את Therapy:Cycle המכיל את Therapy:Medication הנוכחי ולחלץ מתוך Therapy:Cycle/Name את מספר המחזור הסידורי. לדוגמה, Cycle 1 → 1, Repetition Cycle 3, Day 64 → 3. בדיקה מול XML לפני ואחרי מחיקת Cycle הראתה כי CATO מבצע renumbering של Cycle/Name לאחר מחיקת מחזור באמצע התוכנית, ולכן הערך משקף את מספר המחזור הנוכחי בתוכנית. אין להשתמש ב־CycleId, מאחר שהוא מזהה פנימי הנשמר גם כאשר המספר הסידורי של המחזור משתנה.","raw_lexical":"784","type":"string","value":"יש לזהות את Therapy:Cycle המכיל את Therapy:Medication הנוכחי ולחלץ מתוך Therapy:Cycle/Name את מספר המחזור הסידורי. לדוגמה, Cycle 1 → 1, Repetition Cycle 3, Day 64 → 3. בדיקה מול XML לפני ואחרי מחיקת Cycle הראתה כי CATO מבצע renumbering של Cycle/Name לאחר מחיקת מחזור באמצע התוכנית, ולכן הערך משקף את מספר המחזור הנוכחי בתוכנית. אין להשתמש ב־CycleId, מאחר שהוא מזהה פנימי הנשמר גם כאשר המספר הסידורי של המחזור משתנה."},"H":{"header":"Source Business\nDefinition","original":"המספר הסידורי של המחזור שבו נמצאת הוראת התרופה בתוך תוכנית הטיפול של המטופל.","raw_lexical":"752","type":"string","value":"המספר הסידורי של המחזור שבו נמצאת הוראת התרופה בתוך תוכנית הטיפול של המטופל."},"I":{"header":"Target Element name (FHIR)","original":"extension[medication-regimen].extension[currentCycleNumber].valuePositiveInt","raw_lexical":"410","type":"string","value":"extension[medication-regimen].extension[currentCycleNumber].valuePositiveInt"},"J":{"header":"Cardinality","original":"0..1","raw_lexical":"78","type":"string","value":"0..1"},"K":{"header":"Bindings to ValueSet","original":null,"raw_lexical":null,"type":"blank","value":null},"L":{"header":"Mandated code system","original":null,"raw_lexical":null,"type":"blank","value":null},"M":{"header":"Irrelevant under s2t","original":null,"raw_lexical":null,"type":"blank","value":null},"N":{"header":"Example","original":"Cycle 1\n→ 1\n\nRepetition Cycle 2, Day 22\n→ 2\n\nRepetition Cycle 3, Day 43\n→ 3","raw_lexical":"753","type":"string","value":"Cycle 1\n→ 1\n\nRepetition Cycle 2, Day 22\n→ 2\n\nRepetition Cycle 3, Day 43\n→ 3"},"O":{"header":"Exceptions handling","original":null,"raw_lexical":null,"type":"blank","value":null},"P":{"header":"Notes","original":"בדיקה שבוצעה על תוכנית טיפול הראתה כי לאחר מחיקת Cycle באמצע התוכנית, CycleId של המחזורים הנותרים נשמר אך Cycle/Name מתעדכן וממוספר מחדש. לדוגמה, CycleId 2021 השתנה מ־Repetition Cycle 4, Day 64 ל־Repetition Cycle 3, Day 64. לכן Cycle/Name משמש מקור למספר המחזור הנוכחי, בעוד CycleId אינו מתאים ל־currentCycleNumber.","raw_lexical":"785","type":"string","value":"בדיקה שבוצעה על תוכנית טיפול הראתה כי לאחר מחיקת Cycle באמצע התוכנית, CycleId של המחזורים הנותרים נשמר אך Cycle/Name מתעדכן וממוספר מחדש. לדוגמה, CycleId 2021 השתנה מ־Repetition Cycle 4, Day 64 ל־Repetition Cycle 3, Day 64. לכן Cycle/Name משמש מקור למספר המחזור הנוכחי, בעוד CycleId אינו מתאים ל־currentCycleNumber."},"Q":{"header":"Decision Status","original":"FINAL","raw_lexical":"659","type":"string","value":"FINAL"}},"range":"A236:Q236","row":236,"schema":"baseline-import-v1","sheet":"S2T MedicationRequestCato"}'::jsonb, pg_catalog.decode('042c545f61261371190567a061d35691c72314a5e163edef65a56151e3509e56', 'hex'), 'v1', 'v1', (select reference_value_id from pg_temp.bl001_ref where domain_code='CANDIDATE_DISPOSITION' and value_code='ACCEPTED' and version_number=1), 'me:v1:a44a678b70a868c11c76b06c09b4b920e478c233022a577bec0513df9536db1f', '{"canonical_tuple":["ELEMENT_MAPPING","cato","medicationrequest","extension[medication-regimen].extension[currentcyclenumber].valuepositiveint","cato","xml","cato therapy export","therapy:cycle/name",""],"fhir_resource":"MedicationRequest","fixed_value":"","interface_name":"cato therapy export","interface_type":"xml","mapping_kind":"ELEMENT_MAPPING","source_expression":"therapy:cycle/name","source_system":"CATO","source_system_raw":"cato","target_fhir_path":"extension[medication-regimen].extension[currentcyclenumber].valuepositiveint"}'::jsonb),
  ('7fac9a84-7b51-54c8-adb5-670da1abc5a8'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='ELEMENT_MAPPING' and version_number=1), 'S2T MedicationRequestCato', 237, 'A237:Q237', 'baseline-import', 'v1', '{"cells":{"A":{"header":"Source System","original":"CATO ","raw_lexical":"347","type":"string","value":"CATO "},"B":{"header":"Interface Type","original":"XML","raw_lexical":"396","type":"string","value":"XML"},"C":{"header":"Interface Name","original":"CATO Therapy Export","raw_lexical":"243","type":"string","value":"CATO Therapy Export"},"D":{"header":"Field / Expression","original":"/Therapy:Therapy/Cycles/Therapy:Cycle/Items/Therapy:Medication/PrescribedDrugs/PrescribedDrug/ActiveSubstanceInfo/@Name","raw_lexical":"711","type":"string","value":"/Therapy:Therapy/Cycles/Therapy:Cycle/Items/Therapy:Medication/PrescribedDrugs/PrescribedDrug/ActiveSubstanceInfo/@Name"},"E":{"header":"Profile where element is defined","original":"Ext: Medication Regimen HDP","raw_lexical":"399","type":"string","value":"Ext: Medication Regimen HDP"},"F":{"header":"Fixed Value","original":null,"raw_lexical":null,"type":"blank","value":null},"G":{"header":"Transformation \nRules","original":"כאשר Therapy:Medication מכיל PrescribedDrug יחיד ו־ActiveSubstanceInfo/@Name קיים ואינו ריק, יש ליצור מופע יחיד של extension[activeIngredient] ולאכלס את extension[text].valueString בערך המקור. כאשר קיימים מספר מופעי PrescribedDrug תחת אותה הוראה, אין ליצור מספר מופעי activeIngredient, מאחר שקרדינליות activeIngredient היא 0..1. כאשר קיימים מספר מופעי PrescribedDrug תחת אותו Therapy:Medication, כלומר ההוראה כוללת יותר מחומר גנרי אחד, החומרים הפעילים ייוצגו במסגרת Medication.ingredient[].","raw_lexical":"789","type":"string","value":"כאשר Therapy:Medication מכיל PrescribedDrug יחיד ו־ActiveSubstanceInfo/@Name קיים ואינו ריק, יש ליצור מופע יחיד של extension[activeIngredient] ולאכלס את extension[text].valueString בערך המקור. כאשר קיימים מספר מופעי PrescribedDrug תחת אותה הוראה, אין ליצור מספר מופעי activeIngredient, מאחר שקרדינליות activeIngredient היא 0..1. כאשר קיימים מספר מופעי PrescribedDrug תחת אותו Therapy:Medication, כלומר ההוראה כוללת יותר מחומר גנרי אחד, החומרים הפעילים ייוצגו במסגרת Medication.ingredient[]."},"H":{"header":"Source Business\nDefinition","original":"שם החומר הפעיל כפי שמופיע ב־CATO","raw_lexical":"758","type":"string","value":"שם החומר הפעיל כפי שמופיע ב־CATO"},"I":{"header":"Target Element name (FHIR)","original":"extension[medication-regimen].extension[activeIngredient].extension[text].valueString","raw_lexical":"411","type":"string","value":"extension[medication-regimen].extension[activeIngredient].extension[text].valueString"},"J":{"header":"Cardinality","original":"0..1","raw_lexical":"78","type":"string","value":"0..1"},"K":{"header":"Bindings to ValueSet","original":null,"raw_lexical":null,"type":"blank","value":null},"L":{"header":"Mandated code system","original":null,"raw_lexical":null,"type":"blank","value":null},"M":{"header":"Irrelevant under s2t","original":null,"raw_lexical":null,"type":"blank","value":null},"N":{"header":"Example","original":"VinCRIStine Sulfate","raw_lexical":"754","type":"string","value":"VinCRIStine Sulfate"},"O":{"header":"Exceptions handling","original":null,"raw_lexical":null,"type":"blank","value":null},"P":{"header":"Notes","original":"activeIngredient מוגדר בקרדינליות 0..1. לכן כאשר Therapy:Medication כולל PrescribedDrug יחיד ניתן לאכלס את האלמנט. כאשר קיימים מספר מופעי PrescribedDrug תחת אותו Therapy:Medication, כלומר ההוראה כוללת יותר מחומר גנרי אחד, אין לבחור חומר אחד באופן שרירותי ואין ליצור מספר מופעי activeIngredient. החומרים הפעילים ייוצגו במסגרת Medication.ingredient[]. כלל זה מתייחס למספר החומרים הגנריים ב-CATO ואינו תלוי באופן שבו משאב Medication מיוצג ב-FHIR, כ-contained או כ-referenced.","raw_lexical":"790","type":"string","value":"activeIngredient מוגדר בקרדינליות 0..1. לכן כאשר Therapy:Medication כולל PrescribedDrug יחיד ניתן לאכלס את האלמנט. כאשר קיימים מספר מופעי PrescribedDrug תחת אותו Therapy:Medication, כלומר ההוראה כוללת יותר מחומר גנרי אחד, אין לבחור חומר אחד באופן שרירותי ואין ליצור מספר מופעי activeIngredient. החומרים הפעילים ייוצגו במסגרת Medication.ingredient[]. כלל זה מתייחס למספר החומרים הגנריים ב-CATO ואינו תלוי באופן שבו משאב Medication מיוצג ב-FHIR, כ-contained או כ-referenced."},"Q":{"header":"Decision Status","original":"FINAL","raw_lexical":"659","type":"string","value":"FINAL"}},"range":"A237:Q237","row":237,"schema":"baseline-import-v1","sheet":"S2T MedicationRequestCato"}'::jsonb, pg_catalog.decode('fd42a15c70ded72335af55ae0852b46b390227a2ede2f49bf41e85b9a182e982', 'hex'), 'v1', 'v1', (select reference_value_id from pg_temp.bl001_ref where domain_code='CANDIDATE_DISPOSITION' and value_code='ACCEPTED' and version_number=1), 'me:v1:b5fe6b276830e1e6932985c98859feb4aa690bfa64ad104d4ac715f537cf568f', '{"canonical_tuple":["ELEMENT_MAPPING","cato","medicationrequest","extension[medication-regimen].extension[activeingredient].extension[text].valuestring","cato","xml","cato therapy export","/therapy:therapy/cycles/therapy:cycle/items/therapy:medication/prescribeddrugs/prescribeddrug/activesubstanceinfo/@name",""],"fhir_resource":"MedicationRequest","fixed_value":"","interface_name":"cato therapy export","interface_type":"xml","mapping_kind":"ELEMENT_MAPPING","source_expression":"/therapy:therapy/cycles/therapy:cycle/items/therapy:medication/prescribeddrugs/prescribeddrug/activesubstanceinfo/@name","source_system":"CATO","source_system_raw":"cato","target_fhir_path":"extension[medication-regimen].extension[activeingredient].extension[text].valuestring"}'::jsonb),
  ('d06f4be7-5b9d-58a0-bbfe-212d105d73f6'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='ELEMENT_MAPPING' and version_number=1), 'S2T MedicationRequestCato', 238, 'A238:Q238', 'baseline-import', 'v1', '{"cells":{"A":{"header":"Source System","original":"CATO ","raw_lexical":"347","type":"string","value":"CATO "},"B":{"header":"Interface Type","original":"XML","raw_lexical":"396","type":"string","value":"XML"},"C":{"header":"Interface Name","original":"CATO Therapy Export","raw_lexical":"243","type":"string","value":"CATO Therapy Export"},"D":{"header":"Field / Expression","original":"/Therapy:Therapy/Cycles/Therapy:Cycle/Items/Therapy:Medication/PrescribedDrugs/PrescribedDrug/ActiveSubstanceInfo/@UID","raw_lexical":"712","type":"string","value":"/Therapy:Therapy/Cycles/Therapy:Cycle/Items/Therapy:Medication/PrescribedDrugs/PrescribedDrug/ActiveSubstanceInfo/@UID"},"E":{"header":"Profile where element is defined","original":"Ext: Medication Regimen HDP","raw_lexical":"399","type":"string","value":"Ext: Medication Regimen HDP"},"F":{"header":"Fixed Value","original":null,"raw_lexical":null,"type":"blank","value":null},"G":{"header":"Transformation \nRules","original":"כאשר Therapy:Medication מכיל PrescribedDrug יחיד, יש להשתמש ב־ActiveSubstanceInfo/@UID כמפתח לצורך איתור (resolution) של משאב Medication ב־FHIR המייצג את אותו חומר פעיל. אין להעביר את ערך @UID של CATO ישירות ל־FHIR Reference. אם נמצא משאב Medication מתאים, יש לאכלס את extension[activeIngredient].extension[activeIngredientReference].valueReference.reference בפורמט Medication/{Medication.id}. אם לא ניתן לבצע התאמה חד־משמעית, אין לאכלס את activeIngredientReference. כאשר קיימים מספר מופעי PrescribedDrug, אין ליצור מספר מופעי activeIngredientReference; החומרים הפעילים ייוצגו במסגרת Medication.ingredient[]","raw_lexical":"783","type":"string","value":"כאשר Therapy:Medication מכיל PrescribedDrug יחיד, יש להשתמש ב־ActiveSubstanceInfo/@UID כמפתח לצורך איתור (resolution) של משאב Medication ב־FHIR המייצג את אותו חומר פעיל. אין להעביר את ערך @UID של CATO ישירות ל־FHIR Reference. אם נמצא משאב Medication מתאים, יש לאכלס את extension[activeIngredient].extension[activeIngredientReference].valueReference.reference בפורמט Medication/{Medication.id}. אם לא ניתן לבצע התאמה חד־משמעית, אין לאכלס את activeIngredientReference. כאשר קיימים מספר מופעי PrescribedDrug, אין ליצור מספר מופעי activeIngredientReference; החומרים הפעילים ייוצגו במסגרת Medication.ingredient[]"},"H":{"header":"Source Business\nDefinition","original":"הפניה למשאב Medication המייצג את החומר הפעיל.","raw_lexical":"755","type":"string","value":"הפניה למשאב Medication המייצג את החומר הפעיל."},"I":{"header":"Target Element name (FHIR)","original":"extension[medication-regimen].extension[activeIngredient].extension[activeIngredientReference].valueReference","raw_lexical":"412","type":"string","value":"extension[medication-regimen].extension[activeIngredient].extension[activeIngredientReference].valueReference"},"J":{"header":"Cardinality","original":"0..1","raw_lexical":"78","type":"string","value":"0..1"},"K":{"header":"Bindings to ValueSet","original":null,"raw_lexical":null,"type":"blank","value":null},"L":{"header":"Mandated code system","original":null,"raw_lexical":null,"type":"blank","value":null},"M":{"header":"Irrelevant under s2t","original":null,"raw_lexical":null,"type":"blank","value":null},"N":{"header":"Example","original":null,"raw_lexical":null,"type":"blank","value":null},"O":{"header":"Exceptions handling","original":null,"raw_lexical":null,"type":"blank","value":null},"P":{"header":"Notes","original":"ActiveSubstanceInfo/@UID הוא מזהה מקור של CATO בלבד ואינו מזהה Medication של FHIR.\n לצורך המיפוי נדרש מנגנון resolution מוסכם מול מאגר Medication, והמיפוי יבוצע רק כאשר קיימת התאמה חד-משמעית. \nכלל זה מתייחס למספר החומרים הגנריים תחת אותו Therapy:Medication ולא לאופן שבו משאב Medication מיוצג ב-FHIR, בין אם כ-contained ובין אם כ-referenced.\n כאשר קיימים מספר מופעי PrescribedDrug, אין לבחור אחד מהחומרים לצורך activeIngredientReference; החומרים הפעילים מיוצגים באמצעות מערך ingredient של משאב Medication.","raw_lexical":"788","type":"string","value":"ActiveSubstanceInfo/@UID הוא מזהה מקור של CATO בלבד ואינו מזהה Medication של FHIR.\n לצורך המיפוי נדרש מנגנון resolution מוסכם מול מאגר Medication, והמיפוי יבוצע רק כאשר קיימת התאמה חד-משמעית. \nכלל זה מתייחס למספר החומרים הגנריים תחת אותו Therapy:Medication ולא לאופן שבו משאב Medication מיוצג ב-FHIR, בין אם כ-contained ובין אם כ-referenced.\n כאשר קיימים מספר מופעי PrescribedDrug, אין לבחור אחד מהחומרים לצורך activeIngredientReference; החומרים הפעילים מיוצגים באמצעות מערך ingredient של משאב Medication."},"Q":{"header":"Decision Status","original":"WIP","raw_lexical":"722","type":"string","value":"WIP"}},"range":"A238:Q238","row":238,"schema":"baseline-import-v1","sheet":"S2T MedicationRequestCato"}'::jsonb, pg_catalog.decode('360c8843e641fe9f9fa4f324a88e8b9cc568a810db0d09ac8200732b1d598237', 'hex'), 'v1', 'v1', (select reference_value_id from pg_temp.bl001_ref where domain_code='CANDIDATE_DISPOSITION' and value_code='ACCEPTED' and version_number=1), 'me:v1:0607a82d2ddd3507c4e1124ba661faeb991a81410b7bacdcf4e461eeb028d1af', '{"canonical_tuple":["ELEMENT_MAPPING","cato","medicationrequest","extension[medication-regimen].extension[activeingredient].extension[activeingredientreference].valuereference","cato","xml","cato therapy export","/therapy:therapy/cycles/therapy:cycle/items/therapy:medication/prescribeddrugs/prescribeddrug/activesubstanceinfo/@uid",""],"fhir_resource":"MedicationRequest","fixed_value":"","interface_name":"cato therapy export","interface_type":"xml","mapping_kind":"ELEMENT_MAPPING","source_expression":"/therapy:therapy/cycles/therapy:cycle/items/therapy:medication/prescribeddrugs/prescribeddrug/activesubstanceinfo/@uid","source_system":"CATO","source_system_raw":"cato","target_fhir_path":"extension[medi