  ('8baf2e6b-e927-5433-83fb-c93da44d9db2'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'הנחיות נוספות מעודכן', 13, 'A13:F13', 'baseline-import', 'v1', '{"cells":{"A":{"header":"סטטוס/חומרה","original":"לא ניתן למפות","raw_lexical":"605","type":"string","value":"לא ניתן למפות"},"B":{"header":"נושא ההחלטה","original":"rateRatio","raw_lexical":"708","type":"string","value":"rateRatio"},"C":{"header":"אלמנט FHIR","original":"dosageInstruction.doseAndRate.rateRatio","raw_lexical":"354","type":"string","value":"dosageInstruction.doseAndRate.rateRatio"},"D":{"header":"הנחות יסוד","original":"בשלב הנוכחי הוחלט שלא למפות את rateRatio ואת תתי־האלמנטים שלו. ב־CATO קיימים בנפרד נפח ה־Vehicle תחת InfusionSolutions/.../MlVolume ומשך המתן תחת ApplicationInfo/@Duration, אך לא קיים שדה מובנה שמייצג Rate או יחס Volume/Time.\n בנוסף, MlVolume מייצג את נפח נוזל המיהול ואינו בהכרח הנפח הסופי הניתן למטופל, ובקבצים שנבדקו מופיע ExactFinalVolume=false. לכן אין לגזור rateRatio באופן מלאכותי מחלוקת נפח במשך המתן.","raw_lexical":"709","type":"string","value":"בשלב הנוכחי הוחלט שלא למפות את rateRatio ואת תתי־האלמנטים שלו. ב־CATO קיימים בנפרד נפח ה־Vehicle תחת InfusionSolutions/.../MlVolume ומשך המתן תחת ApplicationInfo/@Duration, אך לא קיים שדה מובנה שמייצג Rate או יחס Volume/Time.\n בנוסף, MlVolume מייצג את נפח נוזל המיהול ואינו בהכרח הנפח הסופי הניתן למטופל, ובקבצים שנבדקו מופיע ExactFinalVolume=false. לכן אין לגזור rateRatio באופן מלאכותי מחלוקת נפח במשך המתן."},"E":{"header":"הערות","original":null,"raw_lexical":null,"type":"blank","value":null},"F":{"header":"הערות 17.09.2026","original":null,"raw_lexical":null,"type":"blank","value":null}},"range":"A13:F13","row":13,"schema":"baseline-import-v1","sheet":"הנחיות נוספות מעודכן"}'::jsonb, pg_catalog.decode('0706e265d52082b296a5a40050367dddbaf9ef9567abc7128a333b4b54320b54', 'hex'), 'v1', 'v1',