  ('fe2d1c6b-f758-5a74-a867-3375a51a8940'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'הנחיות נוספות מעודכן', 28, 'A28:F28', 'baseline-import', 'v1', '{"cells":{"A":{"header":"סטטוס/חומרה","original":"לא ניתן למפות","raw_lexical":"605","type":"string","value":"לא ניתן למפות"},"B":{"header":"נושא ההחלטה","original":"sub-dosage-step","raw_lexical":"606","type":"string","value":"sub-dosage-step"},"C":{"header":"אלמנט FHIR","original":"dosageInstruction.extension[sub-dosage-step","raw_lexical":"607","type":"string","value":"dosageInstruction.extension[sub-dosage-step"},"D":{"header":"הנחות יסוד","original":"בשלב הנוכחי הוחלט שלא למפות את ext-sub-dosage-step עבור הוראות המגיעות מ-CATO. בקבצי ה-XML שנבדקו לא נמצא מקור מובנה לשלבי מינון פנימיים הכוללים מספר שלב, מינון, קצב, נפח או משך לכל שלב. \nמרווחים בין מחזורים וימי טיפול בתוך מחזור אינם נחשבים sub-dosage-step, אלא מידע מהפרוטוקול או תזמון מתן. הוראות קליניות המופיעות כטקסט חופשי, כגון העלאת קצב הדרגתית, יישמרו כטקסט תחת dosageInstruction.text או dosageInstruction.additionalInstruction ולא יפורקו אוטומטית לשלבים מובנים.","raw_lexical":"766","type":"string","value":"בשלב הנוכחי הוחלט שלא למפות את ext-sub-dosage-step עבור הוראות המגיעות מ-CATO. בקבצי ה-XML שנבדקו לא נמצא מקור מובנה לשלבי מינון פנימיים הכוללים מספר שלב, מינון, קצב, נפח או משך לכל שלב. \nמרווחים בין מחזורים וימי טיפול בתוך מחזור אינם נחשבים sub-dosage-step, אלא מידע מהפרוטוקול או תזמון מתן. הוראות קליניות המופיעות כטקסט חופשי, כגון העלאת קצב הדרגתית, יישמרו כטקסט תחת dosageInstruction.text או dosageInstruction.additionalInstruction ולא יפורקו אוטומטית לשלבים מובנים."},"E":{"header":"הערות","original":null,"raw_lexical":null,"type":"blank","value":null},"F":{"header":"הערות 17.09.2026","original":null,"raw_lexical":null,"type":"blank","value":null}},"range":"A28:F28","row":28,"schema":"baseline-import-v1","s