  ('5900d38a-7fa5-5c4d-b671-3c6839a4516d'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'הנחיות נוספות מעודכן', 36, 'A36:F36', 'baseline-import', 'v1', '{"cells":{"A":{"header":"סטטוס/חומרה","original":"הוחלט לא למפות","raw_lexical":"773","type":"string","value":"הוחלט לא למפות"},"B":{"header":"נושא ההחלטה","original":"ייצוג של Category ","raw_lexical":"617","type":"string","value":"ייצוג של Category "},"C":{"header":"אלמנט FHIR","original":"category[il-core]","raw_lexical":"178","type":"string","value":"category[il-core]"},"D":{"header":"הנחות יסוד","original":"האלמנט MedicationRequest.category הוגדר כאופציונלי ולא כחובה. המידע הקיים במערכת המקור אינו מאפשר בכל המרכזים הרפואיים לקבוע באופן חד-משמעי אם ההוראה שייכת למסגרת אשפוז או למסגרת אמבולטורית. \nבמרכזים רפואיים שבהם נעשה שימוש בהגדרת Outpatient unit, וככל שיוכח שהגדרה זו משתקפת באופן עקבי ב-XML באמצעות הערך OutPatientCare, ניתן יהיה לשקול שימוש במידע זה לצורך מיפוי האלמנט. במקרים שבהם לא קיים מקור מידע אמין וחד-משמעי, האלמנט לא יאוכלס.","raw_lexical":"618","type":"string","value":"האלמנט MedicationRequest.category הוגדר כאופציונלי ולא כחובה. המידע הקיים במערכת המקור אינו מאפשר בכל המרכזים הרפואיים לקבוע באופן חד-משמעי אם ההוראה שייכת למסגרת אשפוז או למסגרת אמבולטורית. \nבמרכזים רפואיים שבהם נעשה שימוש בהגדרת Outpatient unit, וככל שיוכח שהגדרה זו משתקפת באופן עקבי ב-XML באמצעות הערך OutPatientCare, ניתן יהיה לשקול שימוש במידע זה לצורך מיפוי האלמנט. במקרים שבהם לא קיים מקור מידע אמין וחד-משמעי, האלמנט לא יאוכלס."},"E":{"header":"הערות","original":null,"raw_lexical":null,"type":"blank","value":null},"F":{"header":"הערות 17.09.2026","original":null,"raw_lexical":null,"type":"blank","value":null}},"range":"A36:F36","row":36,"schema":"baseline-import-v1","sheet":"הנחיות נוספות מעודכן"}'::jsonb, pg_catalog.decode('b0a28eb4774858ebf79e716a11ea6727598b6992e7c2a600ee601266