  ('3033e55b-4ff7-5f61-9d3b-f96f86aa05c1'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'הנחיות נוספות מעודכן', 38, 'A38:F38', 'baseline-import', 'v1', '{"cells":{"A":{"header":"סטטוס/חומרה","original":"הוחלט לא למפות","raw_lexical":"773","type":"string","value":"הוחלט לא למפות"},"B":{"header":"נושא ההחלטה","original":"ייצוג של MedicationRequest.encounter","raw_lexical":"621","type":"string","value":"ייצוג של MedicationRequest.encounter"},"C":{"header":"אלמנט FHIR","original":" MedicationRequest.encounter","raw_lexical":"622","type":"string","value":" MedicationRequest.encounter"},"D":{"header":"הנחות יסוד","original":"ב־CATO Therapy Export לא קיים מקור מידע המאפשר לקשר באופן אמין את הוראת התרופה ל־FHIR Encounter. למרות שתוכנית הטיפול ב־CATO נוצרת מתוך הקשר קליני ב־Chameleon, מזהה ה־MedicalRecord אינו נכלל ב־XML המשמש ליצירת משאב ה־MedicationRequest. \nהוחלט שלא לבצע enrichment חיצוני או lookup מול Chameleon לצורך השלמת MedicationRequest.encounter. עבור MedicationRequest שמקורו ב־CATO יוגדר פרופיל DGMC מתאים שבו encounter אינו אלמנט חובה, ולכן MedicationRequest.encounter לא יאוכלס.","raw_lexical":"776","type":"string","value":"ב־CATO Therapy Export לא קיים מקור מידע המאפשר לקשר באופן אמין את הוראת התרופה ל־FHIR Encounter. למרות שתוכנית הטיפול ב־CATO נוצרת מתוך הקשר קליני ב־Chameleon, מזהה ה־MedicalRecord אינו נכלל ב־XML המשמש ליצירת משאב ה־MedicationRequest. \nהוחלט שלא לבצע enrichment חיצוני או lookup מול Chameleon לצורך השלמת MedicationRequest.encounter. עבור MedicationRequest שמקורו ב־CATO יוגדר פרופיל DGMC מתאים שבו encounter אינו אלמנט חובה, ולכן MedicationRequest.encounter לא יאוכלס."},"E":{"header":"הערות","original":"#VALUE!","raw_lexical":"#VALUE!","type":"error","value":"#VALUE!"},"F":{"header":"הערות 17.09.2026","original":"יש ליצור פרופיל DGMC חדש עבור הוראות מ-CATO","raw_lexical":"623","type":"string","value":"יש ליצור פרופיל DGMC חדש עבור הוראות מ-CATO"}},"range":"A38:F38","row":38,"schema":"baseline-import-v1","sheet":"הנחיות נוספות מעודכן"}'::jsonb, pg_catalog.decode('86c647a74ceb840f064076604063188a04a178d97db1b84484175060801fbfe1', 'hex'), 'v1', 'v1', (select reference_value_id from pg_temp.bl001_ref where domain_code='CANDIDATE_DISPOSITION' and value_code='ACCEPTED' and version_number=1), 'me:v1:5f018b8c40b1730975eb2d05112094f31e0960813cb1d0aee90b478b3fb35a50', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.encounter","ייצוג של medicationrequest.encounter","ב־cato therapy export לא קיים מקור מידע המאפשר לקשר באופן אמין את הוראת התרופה ל־fhir encounter. למרות שתוכנית הטיפול ב־cato נוצרת מתוך הקשר קליני ב־chameleon, מזהה ה־medicalrecord אינו נכלל ב־xml המשמש ליצירת משאב ה־medicationrequest. \nהוחלט שלא לבצע enrichment חיצוני או lookup מול chameleon לצורך השלמת medicationrequest.encounter. עבור medicationrequest שמקורו ב־cato יוגדר פרופיל dgmc מתאים שבו encounter אינו אלמנט חובה, ולכן medicationrequest.encounter לא יאוכלס."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.encounter","ייצוג של medicationrequest.encounter","ב־cato therapy export לא קיים מקור מידע המאפשר לקשר באופן אמין את הוראת התרופה ל־fhir encounter. למרות שתוכנית הטיפול ב־cato נוצרת מתוך הקשר קליני ב־chameleon, מזהה ה־medicalrecord אינו נכלל ב־xml המשמש ליצירת משאב ה־medicationrequest. \nהוחלט שלא לבצע enrichment חיצוני או lookup מול chameleon לצורך השלמת medicationrequest.encounter. עבור medicationrequest שמקורו ב־cato יוגדר פרופיל dgmc מתאים שבו encounter אינו אלמנט חובה, ולכן medicationrequest.encounter לא יאוכלס."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb),
  ('2b9a31d7-08ac-56f0-88c7-ecc4119f54a6'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'הנחיות נוספות מעודכן', 39, 'A39:F39', 'baseline-import', 'v1', '{"cells":{"A":{"header":"סטטוס/חומרה","original":"אושר","raw_lexical":"664","type":"string","value":"אושר"},"B":{"header":"נושא ההחלטה","original":"ייצוג של courseOfTherapyType ","raw_lexical":"624","type":"string","value":"ייצוג של courseOfTherapyType "},"C":{"header":"אלמנט FHIR","original":"MedicationRequest.courseOfTherapyType\n","raw_lexical":"625","type":"string","value":"MedicationRequest.courseOfTherapyType\n"},"D":{"header":"הנחות יסוד","original":"MedicationRequest.courseOfTherapyType הוא אלמנט חובה בפרופיל. ב־CATO לא קיים שדה ישיר המייצג את סוג מהלך הטיפול, והערכים הקיימים ב־ValueSet אינם מייצגים באופן מדויק טיפול אונקולוגי מחזורי מבוסס פרוטוקול. לאחר בחינת הערכים הקיימים הוחלט שלא להשתמש בערכים כגון acute, continuous, chronic, PRN או seasonal כאשר הם אינם משקפים נאמנה את משמעות הטיפול. הוחלט ליצור או להרחיב ValueSet כך שיכלול ערכים המתאימים לטיפול אונקולוגי מחזורי ולטיפול אונקולוגי חד־מחזורי. הערך ב־courseOfTherapyType ייקבע בהתאם לסוג תוכנית הטיפול ב־CATO ולכללי הסיווג שיאושרו עבור ה־ValueSet.","raw_lexical":"780","type":"string","value":"MedicationRequest.courseOfTherapyType הוא אלמנט חובה בפרופיל. ב־CATO לא קיים שדה ישיר המייצג את סוג מהלך הטיפול, והערכים הקיימים ב־ValueSet אינם מייצגים באופן מדויק טיפול אונקולוגי מחזורי מבוסס פרוטוקול. לאחר בחינת הערכים הקיימים הוחלט שלא להשתמש בערכים כגון acute, continuous, chronic, PRN או seasonal כאשר הם אינם משקפים נאמנה את משמעות הטיפול. הוחלט ליצור או להרחיב ValueSet כך שיכלול ערכים המתאימים לטיפול אונקולוגי מחזורי ולטיפול אונקולוגי חד־מחזורי. הערך ב־courseOfTherapyType ייקבע בהתאם לסוג תוכנית הטיפול ב־CATO ולכללי הסיווג שיאושרו עבור ה־ValueSet."},"E":{"header":"הערות","original":"היי ראובן,\n\nממה שהבנתי מטה, היית מתחילה בלחזק את התשובות שלך\n\n1.\tAcute- טיפול מחזורי בפרוטוקול אונקולוגי, מלכתחילה מתוכנן לכלול מחזורים נוספים ולכן, אינו מתאים להגדרה של טיפול קצר טווח שאינו צפוי להתחדש.\n2.\tContinuous- הטיפול אינו ניתן באופן רציף, אלא במקטעים (cycles) עם מרווחים בין מתן למתן ולכן, אינו מתאים.\n3.\tChronic- מדובר במהלך טיפולי מוגדר ומובנה במסגרת פרוטוקול ולא, בטיפול כרוני מתמשך לאורך זמן רב (ברוב המכריע של המקרים) ולכן, אינו מתאים.\n4.\tPrn- הטיפול אינו ניתן לפי צורך, אלא לפי הגדרות והנחיות (פרוטוקול) שנקבעו מראש ולכן, אינו מתאים.\n5.\tSeasonal- אין שום קשר לעונתיות בהקשר זה של \"מחזוריות\" ולכן גם הגדרה זו אינה מתאימה.\n\nבהיעדר ערך קיים ב courseofTheraptType, המייצג טיפול מחזורי המבוסס פרוטוקול ובהתאם לעיקרון של ייצוג נאמן של מידע רפואי ללא מניפולציה או פרשנות, אני חושבת שהנכון יהיה להשתמש ב- Extension ייעודי, כך שהמידע הקליני המלא יישמר גם כאשר אין לו ייצוג ב FHIR.\n","raw_lexical":"626","type":"string","value":"היי ראובן,\n\nממה שהבנתי מטה, היית מתחילה בלחזק את התשובות שלך\n\n1.\tAcute- טיפול מחזורי בפרוטוקול אונקולוגי, מלכתחילה מתוכנן לכלול מחזורים נוספים ולכן, אינו מתאים להגדרה של טיפול קצר טווח שאינו צפוי להתחדש.\n2.\tContinuous- הטיפול אינו ניתן באופן רציף, אלא במקטעים (cycles) עם מרווחים בין מתן למתן ולכן, אינו מתאים.\n3.\tChronic- מדובר במהלך טיפולי מוגדר ומובנה במסגרת פרוטוקול ולא, בטיפול כרוני מתמשך לאורך זמן רב (ברוב המכריע של המקרים) ולכן, אינו מתאים.\n4.\tPrn- הטיפול אינו ניתן לפי צורך, אלא לפי הגדרות והנחיות (פרוטוקול) שנקבעו מראש ולכן, אינו מתאים.\n5.\tSeasonal- אין שום קשר לעונתיות בהקשר זה של \"מחזוריות\" ולכן גם הגדרה זו אינה מתאימה.\n\nבהיעדר ערך קיים ב courseofTheraptType, המייצג טיפול מחזורי המבוסס פרוטוקול ובהתאם לעיקרון של ייצוג נאמן של מידע רפואי ללא מניפולציה או פרשנות, אני חושבת שהנכון יהיה להשתמש ב- Extension ייעודי, כך שהמידע הקליני המלא יישמר גם כאשר אין לו ייצוג ב FHIR.\n"},"F":{"header":"הערות 17.09.2026","original":"נדרש ליצור/לעדכן ValueSet שיכלול ייצוג מתאים לטיפול אונקולוגי מחזורי ולטיפול אונקולוגי חד־מחזורי.\nנדרש להשלים כלל סיווג עסקי חד־משמעי מתוך נתוני CATO שיקבע מתי תוכנית טיפול תסווג כ־Cyclic ומתי כ־Single-cycle.\n אין לבצע את הסיווג על בסיס הנחה בלבד עד לאישור הכלל.","raw_lexical":"782","type":"string","value":"נדרש ליצור/לעדכן ValueSet שיכלול ייצוג מתאים לטיפול אונקולוגי מחזורי ולטיפול אונקולוגי חד־מחזורי.\nנדרש להשלים כלל סיווג עסקי חד־משמעי מתוך נתוני CATO שיקבע מתי תוכנית טיפול תסווג כ־Cyclic ומתי כ־Single-cycle.\n אין לבצע את הסיווג על בסיס הנחה בלבד עד לאישור הכלל."}},"range":"A39:F39","row":39,"schema":"baseline-import-v1","sheet":"הנחיות נוספות מעודכן"}'::jsonb, pg_catalog.decode('84070fbe6fe24b6d13b1ae4bc466a779e5bed6867732a0346c7b4cdc337b63bd', 'hex'), 'v1', 'v1', (select reference_value_id from pg_temp.bl001_ref where domain_code='CANDIDATE_DISPOSITION' and value_code='ACCEPTED' and version_number=1), 'me:v1:914cfa7672b1e5fc88884ece5ea44fb6b6a1538c13a19465d8da7959a116bd29', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.courseoftherapytype","ייצוג של courseoftherapytype","medicationrequest.courseoftherapytype הוא אלמנט חובה בפרופיל. ב־cato לא קיים שדה ישיר המייצג את סוג מהלך הטיפול, והערכים הקיימים ב־valueset אינם מייצגים באופן מדויק טיפול אונקולוגי מחזורי מבוסס פרוטוקול. לאחר בחינת הערכים הקיימים הוחלט שלא להשתמש בערכים כגון acute, continuous, chronic, prn או seasonal כאשר הם אינם משקפים נאמנה את משמעות הטיפול. הוחלט ליצור או להרחיב valueset כך שיכלול ערכים המתאימים לטיפול אונקולוגי מחזורי ולטיפול אונקולוגי חד־מחזורי. הערך ב־courseoftherapytype ייקבע בהתאם לסוג תוכנית הטיפול ב־cato ולכללי הסיווג שיאושרו עבור ה־valueset."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.courseoftherapytype","ייצוג של courseoftherapytype","medicationrequest.courseoftherapytype הוא אלמנט חובה בפרופיל. ב־cato לא קיים שדה ישיר המייצג את סוג מהלך הטיפול, והערכים הקיימים ב־valueset אינם מייצגים באופן מדויק טיפול אונקולוגי מחזורי מבוסס פרוטוקול. לאחר בחינת הערכים הקיימים הוחלט שלא להשתמש בערכים כגון acute, continuous, chronic, prn או seasonal כאשר הם אינם משקפים נאמנה את משמעות הטיפול. הוחלט ליצור או להרחיב valueset כך שיכלול ערכים המתאימים לטיפול אונקולוגי מחזורי ולטיפול אונקולוגי חד־מחזורי. הערך ב־courseoftherapytype ייקבע בהתאם לסוג תוכנית הטיפול ב־cato ולכללי הסיווג שיאושרו עבור ה־valueset."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb),
  ('b603ae2c-02d1-513c-bcb8-fd8145b03fcb'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'הנחיות נוספות מעודכן', 40, 'A40:F40', 'baseline-import', 'v1', '{"cells":{"A":{"header":"סטטוס/חומרה","original":"הוחלט לא למפות","raw_lexical":"773","type":"string","value":"הוחלט לא למפות"},"B":{"header":"נושא ההחלטה","original":"ייצוג של משקל / שטח גוף ","raw_lexical":"627","type":"string","value":"ייצוג של משקל / שטח גוף "},"C":{"header":"אלמנט FHIR","original":"MedicationRequest.supportingInformation:bodyWeight\n","raw_lexical":"628","type":"string","value":"MedicationRequest.supportingInformation:bodyWeight\n"},"D":{"header":"הנחות יסוד","original":"מידע אודות משקל המטופל קיים ב- CATO XML תחת   MedicalResults עם זאת, לא קיים קשר מפורש המאפשר לקבוע כי המשקל המופיע ב-  XML הוא המשקל שעל בסיסו חושבה או אושרה הוראת התרופה. \nבנוסף, בהתאם להגדרות CATO עדכון משקל עשוי שלא לעבור למערכת כאשר השינוי אינו חורג מסף מוגדר, לדוגמה 10%, בעוד שהוראה קיימת עשויה להישאר ללא שינוי גם לאחר עדכון משקל. מאחר ש-  supportingInformation:bodyWeight אינו אלמנט חובה בפרופיל, הוחלט בשלב זה שלא למפותו, כדי להימנע מייצוג משקל שאינו בהכרח המשקל הרלוונטי להוראה.","raw_lexical":"629","type":"string","value":"מידע אודות משקל המטופל קיים ב- CATO XML תחת   MedicalResults עם זאת, לא קיים קשר מפורש המאפשר לקבוע כי המשקל המופיע ב-  XML הוא המשקל שעל בסיסו חושבה או אושרה הוראת התרופה. \nבנוסף, בהתאם להגדרות CATO עדכון משקל עשוי שלא לעבור למערכת כאשר השינוי אינו חורג מסף מוגדר, לדוגמה 10%, בעוד שהוראה קיימת עשויה להישאר ללא שינוי גם לאחר עדכון משקל. מאחר ש-  supportingInformation:bodyWeight אינו אלמנט חובה בפרופיל, הוחלט בשלב זה שלא למפותו, כדי להימנע מייצוג משקל שאינו בהכרח המשקל הרלוונטי להוראה."},"E":{"header":"הערות","original":null,"raw_lexical":null,"type":"blank","value":null},"F":{"header":"הערות 17.09.2026","original":null,"raw_lexical":null,"type":"blank",