  ('c75f0888-f05b-5ecf-a202-2787e80e9d7e'::uuid, 'a2c829b0-c10b-554b-9ecd-013f8cd8b327'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'הנחיות נוספות מעודכן', 42, 'A42:F42', 'baseline-import', 'v1', '{"cells":{"A":{"header":"סטטוס/חומרה","original":"אושר","raw_lexical":"664","type":"string","value":"אושר"},"B":{"header":"נושא ההחלטה","original":"ייצוג של הרופא שאישר רפואית את הוראת התרופה במערכת CATO באמצעות מעבר התרופה לסטטוס Physician Verified. רק תרופה שעברה סטטוס זה נחשבת להוראה רפואית פעילה המיועדת ליצירה כ־MedicationRequest","raw_lexical":"633","type":"string","value":"ייצוג של הרופא שאישר רפואית את הוראת התרופה במערכת CATO באמצעות מעבר התרופה לסטטוס Physician Verified. רק תרופה שעברה סטטוס זה נחשבת להוראה רפואית פעילה המיועדת ליצירה כ־MedicationRequest"},"C":{"header":"אלמנט FHIR","original":"MedicationRequest.requester\n","raw_lexical":"634","type":"string","value":"MedicationRequest.requester\n"},"D":{"header":"הנחות יסוד","original":"בהתאם למידול הקיים של הוראות תרופה ממערכת קמיליון, עבור MedicationRequest.requester ייוצג רק requester.reference. תתי־האלמנטים requester.type, requester.identifier ו־requester.display לא ימופו.\nמקור המידע הוא רשומת MedicationState ברמת התרופה שבה State=\"Physician Verified\". יש לשלוף את UserUID של המשתמש החתום על סטטוס זה, לבצע התאמה ל־Practitioner המתאים ולאכלס את requester.reference.\nמאחר שרק תרופה שעברה Physician Verified נחשבת להוראה רפואית פעילה, כל MedicationRequest פעיל צפוי לכלול רופא מאשר שניתן לקשרו ל־Practitioner.\n","raw_lexical":"635","type":"string","value":"בהתאם למידול הקיים של הוראות תרופה ממערכת קמיליון, עבור MedicationRequest.requester ייוצג רק requester.reference. תתי־האלמנטים requester.type, requester.identifier ו־requester.display לא ימופו.\nמקור המידע הוא רשומת MedicationState ברמת התרופה שבה State=\"Physician Verified\". יש לשלוף את UserUID של המשתמש החתום על סטטוס זה, לבצע התאמה ל־Practitioner המתאים ולאכלס את requester.reference.\nמאחר שרק תרופה שעברה Physician Verified נחשבת להוראה רפואית פעילה, כל MedicationRequest פעיל צפוי לכלול רופא מאשר שניתן לקשרו ל־Practitioner.\n"},"E":{"header":"הערות","original":null,"raw_lexical":null,"type":"blank","value":null},"F":{"header":"הערות 17.09.2026","original":null,"raw_lexical":null,"type":"blank","value":null}},"range":"A42:F42","row":42,"schema":"baseline-import-v1","sheet":"הנחיות נוספות מעודכן"}'::jsonb, pg_catalog.decode('0ed9d4badb15c235e3033852008f12c14ea6d3ddfdcd50575202f18a0b6ff5cc', 'hex'), 'v1', 'v1', (select reference_value_id from pg_temp.bl001_ref where domain_code='CANDIDATE_DISPOSITION' and value_code='ACCEPTED' and version_number=1), 'me:v1:2d6a04a76609f7e1718876d90d93e432349c9cb5d487e23035c88ba8984cc797', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.requester","ייצוג של הרופא שאישר רפואית את הוראת התרופה במערכת cato באמצעות מעבר התרופה לסטטוס physician verified. רק תרופה שעברה סטטוס זה נחשבת להוראה רפואית פעילה המיועדת ליצירה כ־medicationrequest","בהתאם למידול הקיים של הוראות תרופה ממערכת קמיליון, עבור medicationrequest.requester ייוצג רק requester.reference. תתי־האלמנטים requester.type, requester.identifier ו־requester.display לא ימופו.\nמקור המידע הוא רשומת medicationstate ברמת התרופה שבה state=\"physician verified\". יש לשלוף את useruid של המשתמש החתום על סטטוס זה, לבצע התאמה ל־practitioner המתאים ולאכלס את requester.reference.\nמאחר שרק תרופה שעברה physician verified נחשבת להוראה רפואית פעילה, כל medicationrequest פעיל צפוי לכלול רופא מאשר שניתן לקשרו ל־practitioner."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.requester","ייצוג של הרופא שאישר רפואית את הוראת התרופה במערכת cato באמצעות מעבר התרופה לסטטוס physician verified. רק תרופה שעברה סטטוס זה נחשבת להוראה רפואית פעילה המיועדת ליצירה כ־medicationrequest","בהתאם למידול הקיים של הוראות תרופה ממערכת קמיליון, עבור medicationrequest.requester ייוצג רק requester.reference. תתי־האלמנטים requester.type, requester.identifier ו־requester.display לא ימופו.\nמקור המידע הוא רשומת medicationstate ברמת התרופה שבה state=\"physician verified\". יש לשלוף את useruid של המשתמש החתום על סטטוס זה, לבצע התאמה ל־practitioner המתאים ולאכלס את requester.reference.\nמאחר שרק תרופה שעברה physician verified נחשבת להוראה רפואית פעילה, כל medicationrequest פעיל צפוי לכלול רופא מאשר שניתן לקשרו ל־practitioner."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb),
