  ('83808643-991b-57b7-9da1-fb823f6ec912'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:f1d2cc9b91edc93cb57c4ac3101b2f8aab8cf0772c0890d36c8e325bc84e12ec', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.doseandrate.type","ערך calculated ב-doseandrate.type","בשלב הנוכחי הוחלט שלא למפות את הערך calculated באלמנט dosageinstruction.doseandrate.type. המיפוי יתבסס על המינון הסופי שהוזמן בפועל ב-cato מתוך prescribeddose/finaldose, ולכן הערך שיאוכלס יהיה ordered. \nנתוני חישוב כגון usualdoserelative, modifiedusualdoserelative, relativedose, bsa, weight ו-dosemodificationpercent לא ימופו בשלב זה כ-doseandrate נפרד, מאחר שהם מייצגים את לוגיקת החישוב של cato ולא את ההוראה הסופית לביצוע.\n ניתן יהיה לבחון מיפוי של calculated בשלב עתידי, אם תתקבל החלטה לשמר גם את מנגנון החישוב הקליני באופן מובנה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.doseandrate.type","ערך calculated ב-doseandrate.type","בשלב הנוכחי הוחלט שלא למפות את הערך calculated באלמנט dosageinstruction.doseandrate.type. המיפוי יתבסס על המינון הסופי שהוזמן בפועל ב-cato מתוך prescribeddose/finaldose, ולכן הערך שיאוכלס יהיה ordered. \nנתוני חישוב כגון usualdoserelative, modifiedusualdoserelative, relativedose, bsa, weight ו-dosemodificationpercent לא ימופו בשלב זה כ-doseandrate נפרד, מאחר שהם מייצגים את לוגיקת החישוב של cato ולא את ההוראה הסופית לביצוע.\n ניתן יהיה לבחון מיפוי של calculated בשלב עתידי, אם תתקבל החלטה לשמר גם את מנגנון החישוב הקליני באופן מובנה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('4aecb010-565e-5e07-b409-1b73736b19b4'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:fe3b2c034623d84ca6af21e1c8b6f5873d2ce5bd0b3b56998e940e352f095d68', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.doseandrate.dose[x]","doserange","בקבצי ה־xml שנבדקו ממערכת cato המינון מיוצג כערך יחיד: בהוראות הכוללות prescribeddrug מתוך prescribeddose/finaldose/datatypes:quantity, ובהוראות perfusion ללא prescribeddrug מתוך נפח התמיסה (mlvolume). לא זוהה מבנה המייצג טווח מובנה של מינון נמוך וגבוה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.doseandrate.dose[x]","doserange","בקבצי ה־xml שנבדקו ממערכת cato המינון מיוצג כערך יחיד: בהוראות הכוללות prescribeddrug מתוך prescribeddose/finaldose/datatypes:quantity, ובהוראות perfusion ללא prescribeddrug מתוך נפח התמיסה (mlvolume). לא זוהה מבנה המייצג טווח מובנה של מינון נמוך וגבוה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('a4da2753-15e9-51d6-9df0-b3db1094e73d'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:0c00dc8bc802e4fa421c78369af6266a540a93de121f1dd68518c5605e3dff1e', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.doseandrate.rate[x]","raterange","שלב הנוכחי הוחלט שלא למפות את האלמנט raterange. בקבצי ה־xml שנבדקו ממערכת cato לא קיים מבנה מובנה המייצג טווח קצב מתן עם ערך תחתון וערך עליון. לכן לא ימופו raterange.low ו־raterange.high. אין ליצור טווח קצב מלאכותי על בסיס ערך יחיד, נפח, משך מתן או חישוב נגזר. \nאם בעתיד יזוהה ב־cato מקור מובנה המייצג טווח קצב מתן אמיתי, ניתן יהיה לשקול מיפוי ייעודי ל־raterange."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.doseandrate.rate[x]","raterange","שלב הנוכחי הוחלט שלא למפות את האלמנט raterange. בקבצי ה־xml שנבדקו ממערכת cato לא קיים מבנה מובנה המייצג טווח קצב מתן עם ערך תחתון וערך עליון. לכן לא ימופו raterange.low ו־raterange.high. אין ליצור טווח קצב מלאכותי על בסיס ערך יחיד, נפח, משך מתן או חישוב נגזר. \nאם בעתיד יזוהה ב־cato מקור מובנה המייצג טווח קצב מתן אמיתי, ניתן יהיה לשקול מיפוי ייעודי ל־raterange."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('cc6cc039-5fe5-51d7-965e-a6d2d87b9a4f'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:65e03d407650d76e04962050f0e5ef58acdacb9d4c415fc6bd1222564871c99a', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.doseandrate.rate[x]-ratequantity","ratequantity","בשלב הנוכחי הוחלט שלא למפות את ratequantity ואת תתי־האלמנטים שלו. במערכת cato לא קיים שדה ייעודי להזנת קצב מתן מפורש, כגון ml/hour או mg/hour. המידע הקיים במקור הוא נפח ה־vehicle ומשך המתן כשני נתונים נפרדים. אין לחשב מהם ratequantity, כדי לא ליצור ערך שאינו קיים במערכת המקור."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.doseandrate.rate[x]-ratequantity","ratequantity","בשלב הנוכחי הוחלט שלא למפות את ratequantity ואת תתי־האלמנטים שלו. במערכת cato לא קיים שדה ייעודי להזנת קצב מתן מפורש, כגון ml/hour או mg/hour. המידע הקיים במקור הוא נפח ה־vehicle ומשך המתן כשני נתונים נפרדים. אין לחשב מהם ratequantity, כדי לא ליצור ערך שאינו קיים במערכת המקור."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('977d7334-fc49-566c-99ed-192097dc7587'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:0b523de07ec215abbef4169f800c2c47df7455cbd6aa85299d7c75a136d3a4eb', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.doseandrate.rateratio","rateratio","בשלב הנוכחי הוחלט שלא למפות את rateratio ואת תתי־האלמנטים שלו. ב־cato קיימים בנפרד נפח ה־vehicle תחת infusionsolutions/.../mlvolume ומשך המתן תחת applicationinfo/@duration, אך לא קיים שדה מובנה שמייצג rate או יחס volume/time.\n בנוסף, mlvolume מייצג את נפח נוזל המיהול ואינו בהכרח הנפח הסופי הניתן למטופל, ובקבצים שנבדקו מופיע exactfinalvolume=false. לכן אין לגזור rateratio באופן מלאכותי מחלוקת נפח במשך המתן."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.doseandrate.rateratio","rateratio","בשלב הנוכחי הוחלט שלא למפות את rateratio ואת תתי־האלמנטים שלו. ב־cato קיימים בנפרד נפח ה־vehicle תחת infusionsolutions/.../mlvolume ומשך המתן תחת applicationinfo/@duration, אך לא קיים שדה מובנה שמייצג rate או יחס volume/time.\n בנוסף, mlvolume מייצג את נפח נוזל המיהול ואינו בהכרח הנפח הסופי הניתן למטופל, ובקבצים שנבדקו מופיע exactfinalvolume=false. לכן אין לגזור rateratio באופן מלאכותי מחלוקת נפח במשך המתן."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('16178d0d-e331-518f-bc16-8b8e0dbcb9db'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:529b5b3d8c52f0ef3ea2146e49020eef1587b6c780d35f1c5bb090b844e658c9', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.doseandrate.rate[x]-raterange","raterange","בשלב הנוכחי הוחלט שלא למפות את raterange. בקבצי ה־xml שנבדקו ממערכת cato לא קיים מבנה מובנה של טווח קצב מתן הכולל ערך נמוך וערך גבוה. לכן לא ימופו raterange.low ו־raterange.high. אין ליצור טווח מלאכותי על בסיס ערך יחיד, נפח, משך מתן או חישוב נגזר."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.doseandrate.rate[x]-raterange","raterange","בשלב הנוכחי הוחלט שלא למפות את raterange. בקבצי ה־xml שנבדקו ממערכת cato לא קיים מבנה מובנה של טווח קצב מתן הכולל ערך נמוך וערך גבוה. לכן לא ימופו raterange.low ו־raterange.high. אין ליצור טווח מלאכותי על בסיס ערך יחיד, נפח, משך מתן או חישוב נגזר."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('d823fdfc-1422-597a-9ccb-29ba3279881d'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:cba45c7aa88bcc95e5d3a03c4efb72356c390ca9cae5af282d3c416534ed873e', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationcodeableconcept.coding[snomed] /\ncontained.ingredient.itemcodeableconcept.coding[snomed]","ingredient external coding","לצורך מיפוי תרופות וחומרים פעילים מ־cato ל־snomed ct, ייעשה שימוש במנגנון ההמרה הקיים של קטלוג התרופות בקמיליון, ולא תנוהל טבלת המרה נפרדת עבור cato.\nמזהה חומר הפעיל המתקבל מ־cato מתוך activesubstanceinfo/@uid ישמש כמפתח לחיפוש מול העמודה drugs.cato_code בקמיליון. כאשר נמצאה התאמה חד־משמעית, רשומת התרופה המתאימה ב־drugs תשמש כנקודת הכניסה למנגנון המיפוי הקיים של קמיליון ל־snomed ct.\nכלומר, תהליך ה־resolution יהיה:\ncato activesubstanceinfo/@uid → drugs.cato_code → drugs.code / רשומת התרופה בקמיליון → מנגנון ההמרה הקיים ל־snomed ct.\nכאשר לא נמצאה התאמה חד־משמעית ב־drugs.cato_code, אין לבצע התאמה על בסיס שם התרופה או דמיון טקסטואלי, ואין לייצר קוד snomed באופן מלאכותי. במקרה כזה coding[snomed] לא יאוכלס ויש לתעד את החוסר לצורך תחזוקת קטלוג התרופות."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationcodeableconcept.coding[snomed] /\ncontained.ingredient.itemcodeableconcept.coding[snomed]","ingredient external coding","לצורך מיפוי תרופות וחומרים פעילים מ־cato ל־snomed ct, ייעשה שימוש במנגנון ההמרה הקיים של קטלוג התרופות בקמיליון, ולא תנוהל טבלת המרה נפרדת עבור cato.\nמזהה חומר הפעיל המתקבל מ־cato מתוך activesubstanceinfo/@uid ישמש כמפתח לחיפוש מול העמודה drugs.cato_code בקמיליון. כאשר נמצאה התאמה חד־משמעית, רשומת התרופה המתאימה ב־drugs תשמש כנקודת הכניסה למנגנון המיפוי הקיים של קמיליון ל־snomed ct.\nכלומר, תהליך ה־resolution יהיה:\ncato activesubstanceinfo/@uid → drugs.cato_code → drugs.code / רשומת התרופה בקמיליון → מנגנון ההמרה הקיים ל־snomed ct.\nכאשר לא נמצאה התאמה חד־משמעית ב־drugs.cato_code, אין לבצע התאמה על בסיס שם התרופה או דמיון טקסטואלי, ואין לייצר קוד snomed באופן מלאכותי. במקרה כזה coding[snomed] לא יאוכלס ויש לתעד את החוסר לצורך תחזוקת קטלוג התרופות."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('4be771c7-502b-57c8-9967-edaf14f932ac'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:5b8a09e1da73aa4040e357e844097ca9f64df9d60ff02d10102f741c373707e3', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.doseandrate.dose[x]","משמעות dose[x]","האלמנט dosageinstruction.doseandrate.dose[x] מייצג את הכמות של ה־medication נשוא ההוראה שיש לתת למטופל במופע מתן אחד.\nכאשר ההוראה כוללת prescribeddrug יחיד וקיים מינון סופי תחת prescribeddose/finaldose/datatypes:quantity, יש למפות את המינון הסופי ל־dosequantity.\nכאשר ההוראה מסוג perfusion ואינה כוללת prescribeddrug, והתמיסה תחת infusionsolutions/solution היא עצמה תוכן הוראת המתן, ניתן למפות את mlvolume ל־dosequantity ביחידת ml.\nכאשר קיימים prescribeddrug אחד או יותר ובנוסף infusionsolutions, אין למפות את mlvolume ל־dosequantity, מאחר שהוא מייצג את נפח ה־vehicle / diluent ולא בהכרח את הנפח הסופי הניתן למטופל. במקרה כזה מינוני החומרים הפעילים מיוצגים ברמת medication.ingredient, ואין ליצור dosequantity נוסף עבור נוזל המיהול.\nכאשר קיימים מספר prescribeddrug באותה הוראה, אין ליצור מספר מופעי doseandrate.dosequantity עבור כל החומרים, מאחר שאין ב־doseandrate מנגנון המקשר כל dose ל־ingredient מסוים.\ndoserange לא ימופה בשלב הנוכחי. אם בעתיד יזוהה ב־cato מקור מובנה המייצג טווח מינון אמיתי, ניתן יהיה לבחון מיפוי ייעודי."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.doseandrate.dose[x]","משמעות dose[x]","האלמנט dosageinstruction.doseandrate.dose[x] מייצג את הכמות של ה־medication נשוא ההוראה שיש לתת למטופל במופע מתן אחד.\nכאשר ההוראה כוללת prescribeddrug יחיד וקיים מינון סופי תחת prescribeddose/finaldose/datatypes:quantity, יש למפות את המינון הסופי ל־dosequantity.\nכאשר ההוראה מסוג perfusion ואינה כוללת prescribeddrug, והתמיסה תחת infusionsolutions/solution היא עצמה תוכן הוראת המתן, ניתן למפות את mlvolume ל־dosequantity ביחידת ml.\nכאשר קיימים prescribeddrug אחד או יותר ובנוסף infusionsolutions, אין למפות את mlvolume ל־dosequantity, מאחר שהוא מייצג את נפח ה־vehicle / diluent ולא בהכרח את הנפח הסופי הניתן למטופל. במקרה כזה מינוני החומרים הפעילים מיוצגים ברמת medication.ingredient, ואין ליצור dosequantity נוסף עבור נוזל המיהול.\nכאשר קיימים מספר prescribeddrug באותה הוראה, אין ליצור מספר מופעי doseandrate.dosequantity עבור כל החומרים, מאחר שאין ב־doseandrate מנגנון המקשר כל dose ל־ingredient מסוים.\ndoserange לא ימופה בשלב הנוכחי. אם בעתיד יזוהה ב־cato מקור מובנה המייצג טווח מינון אמיתי, ניתן יהיה לבחון מיפוי ייעודי."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('985c0b27-03ad-56e0-ab7e-88fdfc4f0da3'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:3be0db980f056d533b948550c0af8940e1fbef19378f5bc59672bdfb0562feb1', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.contained / medicationreference","contained medication לתרופה עם נוזל או קוקטייל","במקרים שבהם הוראת cato כוללת תרופה עם נוזל אינפוזיה, או תמהיל הכולל מספר prescribeddrug תחת אותה הוראה, הוחלט לייצג את התרופה באמצעות medicationrequest.medicationreference המצביע ל-contained medication.\n ה-contained medication יתאר את הרכב התמהיל באמצעות medication.ingredient: כל prescribeddrug ימופה כ-ingredient פעיל עם isactive=true, וכל infusionsolutions/solution ימופה כ-ingredient לא פעיל עם isactive=false. מזהה ה-contained ייגזר\n מ-therapy:medication/uid, וה-reference יפנה אליו באמצעות #. לא ייווצר קוד מוצר מלאכותי לתמהיל אם אינו קיים במקור; במקרה כזה יש למלא code.text בלבד. \nקידוד snomed ct עבור החומרים הפעילים יתבצע באמצעות מנגנון ההמרה הקיים של קמיליון: activesubstanceinfo/@uid מ־cato יושווה ל־drugs.cato_code, ולאחר התאמה חד־משמעית תופעל לוגיקת ההמרה הקיימת של קמיליון ל־snomed ct. \nאם לא נמצאה התאמה חד־משמעית או שאין מיפוי snomed תקף, הקידוד החיצוני לא יאוכלס.\nמינוני ה־prescribeddrugs ונפח ה־infusionsolution הם מאפיינים של הרכב ה־medication ואינם מתורגמים למספר מופעי dosageinstruction.doseandrate.dosequantity. \nכל prescribeddrug ייוצג כ־medication.ingredient עם הכמות המתאימה לו בהתאם למידול שנקבע, וה־infusionsolution ייוצג כמרכיב הלא־פעיל של התמהיל. אין להשתמש בנפח ה־vehicle כ־dose של החומר הפעיל."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.contained / medicationreference","contained medication לתרופה עם נוזל או קוקטייל","במקרים שבהם הוראת cato כוללת תרופה עם נוזל אינפוזיה, או תמהיל הכולל מספר prescribeddrug תחת אותה הוראה, הוחלט לייצג את התרופה באמצעות medicationrequest.medicationreference המצביע ל-contained medication.\n ה-contained medication יתאר את הרכב התמהיל באמצעות medication.ingredient: כל prescribeddrug ימופה כ-ingredient פעיל עם isactive=true, וכל infusionsolutions/solution ימופה כ-ingredient לא פעיל עם isactive=false. מזהה ה-contained ייגזר\n מ-therapy:medication/uid, וה-reference יפנה אליו באמצעות #. לא ייווצר קוד מוצר מלאכותי לתמהיל אם אינו קיים במקור; במקרה כזה יש למלא code.text בלבד. \nקידוד snomed ct עבור החומרים הפעילים יתבצע באמצעות מנגנון ההמרה הקיים של קמיליון: activesubstanceinfo/@uid מ־cato יושווה ל־drugs.cato_code, ולאחר התאמה חד־משמעית תופעל לוגיקת ההמרה הקיימת של קמיליון ל־snomed ct. \nאם לא נמצאה התאמה חד־משמעית או שאין מיפוי snomed תקף, הקידוד החיצוני לא יאוכלס.\nמינוני ה־prescribeddrugs ונפח ה־infusionsolution הם מאפיינים של הרכב ה־medication ואינם מתורגמים למספר מופעי dosageinstruction.doseandrate.dosequantity. \nכל prescribeddrug ייוצג כ־medication.ingredient עם הכמות המתאימה לו בהתאם למידול שנקבע, וה־infusionsolution ייוצג כמרכיב הלא־פעיל של התמהיל. אין להשתמש בנפח ה־vehicle כ־dose של החומר הפעיל."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('d4d9807e-32d3-5709-b42a-2355451a887a'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:75cad769efd2841b271e5ef59006e3da7b93312999e8159cb9c264eb9a312088', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","contained.identifier vs contained.code","medication number / uid","במקרים שבהם הוראת cato כוללת medication number/uid אחד המייצג את כל פריט ההוראה, כולל התרופה ונוזל המיהול, המזהה ימופה ל-contained.identifier.\n ה-contained.code ישמש לתיאור התמהיל עצמו, למשל שם התרופה יחד עם נוזל המיהול. לא ייווצר code.coding לתמהיל על בסיס medication number, אלא אם תתקבל החלטה ארגונית שמזהה זה משמש כקוד מקומי של התמהיל ולא רק כמזהה טכני של ההוראה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["contained.identifier vs contained.code","medication number / uid","במקרים שבהם הוראת cato כוללת medication number/uid אחד המייצג את כל פריט ההוראה, כולל התרופה ונוזל המיהול, המזהה ימופה ל-contained.identifier.\n ה-contained.code ישמש לתיאור התמהיל עצמו, למשל שם התרופה יחד עם נוזל המיהול. לא ייווצר code.coding לתמהיל על בסיס medication number, אלא אם תתקבל החלטה ארגונית שמזהה זה משמש כקוד מקומי של התמהיל ולא רק כמזהה טכני של ההוראה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('a1267ac4-4ab8-5f41-a6a0-84a696752a5a'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:1ed1126142c6bca26f271d36483b193b0d5c21dd712606aef29e4577eb13b3f2', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","contained.code","contained.code.coding","בשלב הנוכחי הוחלט שלא למפות את contained.code.coding עבור תמהיל התרופה, מאחר שלא זוהה בקובצי ה-xml קוד סמנטי מובנה המייצג את התמהיל עצמו. medication uid / medication number מייצג את מזהה פריט ההוראה ב-cato ולכן ימופה ל-contained.identifier ולא ל-contained.code.coding.\n תיאור התמהיל ימופה ל-contained.code.text באמצעות שילוב שם התרופה או התרופות עם נוזל המיהול. מיפוי ל-code.coding יישקל רק אם תוגדר מערכת קידוד מקומית מאושרת לתמהילים או מוצרי תרופה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["contained.code","contained.code.coding","בשלב הנוכחי הוחלט שלא למפות את contained.code.coding עבור תמהיל התרופה, מאחר שלא זוהה בקובצי ה-xml קוד סמנטי מובנה המייצג את התמהיל עצמו. medication uid / medication number מייצג את מזהה פריט ההוראה ב-cato ולכן ימופה ל-contained.identifier ולא ל-contained.code.coding.\n תיאור התמהיל ימופה ל-contained.code.text באמצעות שילוב שם התרופה או התרופות עם נוזל המיהול. מיפוי ל-code.coding יישקל רק אם תוגדר מערכת קידוד מקומית מאושרת לתמהילים או מוצרי תרופה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('8834b73d-f329-552b-bc81-9c4c6f89dfce'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:0057c91c2061e798138a960547066ae7b7b93070b4e19a8d2ff59328417d7307', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.timing","timing כללי","בשלב הנוכחי הוחלט למפות את תזמון הוראת התרופה ב־cato באמצעות dosageinstruction.timing.event ו־dosageinstruction.timing.repeat.duration. תאריך ההוראה ימופה מתוך therapy:medication/date ל־timing.event ברמת דיוק של תאריך (yyyy-mm-dd). משך המתן ימופה מתוך datatypes:applicationinfo/@duration אל timing.repeat.duration, כאשר יחידת הזמן היא דקות ותאוכלס בנפרד ב־timing.repeat.durationunit בערך min. אין למפות אלמנטים נוספים של חזרתיות אלא אם קיים עבורם מקור מפורש ומאושר ב־cato."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.timing","timing כללי","בשלב הנוכחי הוחלט למפות את תזמון הוראת התרופה ב־cato באמצעות dosageinstruction.timing.event ו־dosageinstruction.timing.repeat.duration. תאריך ההוראה ימופה מתוך therapy:medication/date ל־timing.event ברמת דיוק של תאריך (yyyy-mm-dd). משך המתן ימופה מתוך datatypes:applicationinfo/@duration אל timing.repeat.duration, כאשר יחידת הזמן היא דקות ותאוכלס בנפרד ב־timing.repeat.durationunit בערך min. אין למפות אלמנטים נוספים של חזרתיות אלא אם קיים עבורם מקור מפורש ומאושר ב־cato."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('6c967d64-5c8a-5094-acd4-bb060bb48635'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:3bef36c7e798ebc0be3308cbb2bafb5e481245f667684b9f1f0e222dcd3967c2', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.timing.repeat","אלמנטים של חזרתיות ב-timing","לא ימופו בשלב זה אלמנטים של תבנית חזרתיות כגון frequency, period, periodunit, dayofweek, timeofday, boundsduration, boundsrange ו-boundsperiod, מאחר שבקבצי ה-xml שנבדקו המידע מופיע כאירועי מתן ספציפיים ולא כתבנית מינון חוזרת מובנית. \nכמו כן, relativeadministrationdatetime לא ימופה ל-timing.repeat.offset, מאחר שהוא מייצג יחס בין שתי הוראות תרופה שונות ולא offset רגיל של timing."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.timing.repeat","אלמנטים של חזרתיות ב-timing","לא ימופו בשלב זה אלמנטים של תבנית חזרתיות כגון frequency, period, periodunit, dayofweek, timeofday, boundsduration, boundsrange ו-boundsperiod, מאחר שבקבצי ה-xml שנבדקו המידע מופיע כאירועי מתן ספציפיים ולא כתבנית מינון חוזרת מובנית. \nכמו כן, relativeadministrationdatetime לא ימופה ל-timing.repeat.offset, מאחר שהוא מייצג יחס בין שתי הוראות תרופה שונות ולא offset רגיל של timing."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('f62e3067-5ef0-5434-b006-d1e193229bd5'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:ab48164b7759a38ab5ce308e15c517f63a129e01f17cca146ccf688a25920bc8', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.timing.event","משמעות timing.event","האלמנט dosageinstruction.timing.event מייצג את מועד המתן המתוכנן של ההוראה. בקבצי cato הוא ימופה מתוך therapy:medication/date ברמת דיוק של תאריך (yyyy-mm-dd).\n אין להשתמש ב־event לתיאור משך המתן. משך המתן ימופה בנפרד ל־timing.repeat.duration מתוך datatypes:applicationinfo/@duration."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.timing.event","משמעות timing.event","האלמנט dosageinstruction.timing.event מייצג את מועד המתן המתוכנן של ההוראה. בקבצי cato הוא ימופה מתוך therapy:medication/date ברמת דיוק של תאריך (yyyy-mm-dd).\n אין להשתמש ב־event לתיאור משך המתן. משך המתן ימופה בנפרד ל־timing.repeat.duration מתוך datatypes:applicationinfo/@duration."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('b5ac524c-c6f5-5209-909a-6191c9ffc16e'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:9b32d80afe5e63b2178d83a23fd647dc5fbcb395e3dad32ca44dea783b62ecdd', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.timing.repeat","משמעות timing.repeat","יש ליצור את dosageinstruction.timing.repeat כאשר ממופה timing.repeat.duration. במערכת cato הערך datatypes:applicationinfo/@duration מייצג את משך המתן של ההוראה\n ולכן ימופה ל־timing.repeat.duration. אין לפרש את עצם קיום repeat כהוראה חוזרת; במיפוי זה הוא משמש כאובייקט fhir לצורך ייצוג משך המתן."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.timing.repeat","משמעות timing.repeat","יש ליצור את dosageinstruction.timing.repeat כאשר ממופה timing.repeat.duration. במערכת cato הערך datatypes:applicationinfo/@duration מייצג את משך המתן של ההוראה\n ולכן ימופה ל־timing.repeat.duration. אין לפרש את עצם קיום repeat כהוראה חוזרת; במיפוי זה הוא משמש כאובייקט fhir לצורך ייצוג משך המתן."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('c1c0ed14-c948-560d-857f-48cbb48cad90'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:526a8607b7e7c8ffc9f236a8cb53a870d246000925280bf8cb2c048064284e6d', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.timing.repeat.bounds[x]","bounds[x]","בשלב הנוכחי הוחלט שלא למפות את dosageinstruction.timing.repeat.bounds[x] ואת תתי-האלמנטים שלו. בקבצי ה-xml שנבדקו ממערכת cato ההוראות מיוצגות כאירועי מתן ספציפיים באמצעות therapy:medication/date, ולא כתבנית חזרתיות בעלת גבולות התחלה וסיום.\nמשך המתן של ההוראה מיוצג בנפרד באמצעות datatypes:applicationinfo/@duration ולכן ימופה ל-timing.repeat.duration ולא ל-boundsduration. כמו כן, therapy:cycle/startdate מייצג את תחילת המחזור ולא ישמש כ-boundsperiod של הוראת התרופה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.timing.repeat.bounds[x]","bounds[x]","בשלב הנוכחי הוחלט שלא למפות את dosageinstruction.timing.repeat.bounds[x] ואת תתי-האלמנטים שלו. בקבצי ה-xml שנבדקו ממערכת cato ההוראות מיוצגות כאירועי מתן ספציפיים באמצעות therapy:medication/date, ולא כתבנית חזרתיות בעלת גבולות התחלה וסיום.\nמשך המתן של ההוראה מיוצג בנפרד באמצעות datatypes:applicationinfo/@duration ולכן ימופה ל-timing.repeat.duration ולא ל-boundsduration. כמו כן, therapy:cycle/startdate מייצג את תחילת המחזור ולא ישמש כ-boundsperiod של הוראת התרופה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('a3046517-9e81-5898-b3dc-bd5e1cd891cc'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:a8adb709a8515cb4c3a259bf0e7caf477708daa83acbc5254f48c21776cc691a', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.timing.repeat.count","count ו-countmax","הוחלט שלא למפות את dosageinstruction.timing.repeat.count ואת countmax. ב־cato xml לא קיים מקור מפורש המייצג את מספר הפעמים שיש לבצע את המתן במסגרת הוראת ה־dosage. \nאין לגזור count=1 מעצם העובדה שמופע therapy:medication מייצג הוראת מתן ספציפית, ואין להשתמש במספר המחזורים או מספר ימי הטיפול לצורך אכלוס אלמנטים אלה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.timing.repeat.count","count ו-countmax","הוחלט שלא למפות את dosageinstruction.timing.repeat.count ואת countmax. ב־cato xml לא קיים מקור מפורש המייצג את מספר הפעמים שיש לבצע את המתן במסגרת הוראת ה־dosage. \nאין לגזור count=1 מעצם העובדה שמופע therapy:medication מייצג הוראת מתן ספציפית, ואין להשתמש במספר המחזורים או מספר ימי הטיפול לצורך אכלוס אלמנטים אלה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('3142f920-6038-5991-a323-8b8ede5fb3bf'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:81aceb093f5c1b2e8bd96b487badbf13bb5e42a90038b8be9b3516092015f11d', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationstates / dosageinstruction.timing.repeat.timeofday","setdatetime ו-timeofday","בשלב הנוכחי הוחלט שלא למפות את medicationstates/medicationstate/@setdatetime ל־dosageinstruction.timing.repeat.timeofday. ערך setdatetime מייצג זמן שינוי סטטוס במערכת cato, כגון planned, order approved או physician verified, ואינו מייצג בהכרח את שעת המתן המתוכננת למטופל. לכן הוא לא ישמש לתיאור תזמון המינון. מועד המתן המתוכנן ימופה מתוך therapy:medication/date ל־dosageinstruction.timing.event."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationstates / dosageinstruction.timing.repeat.timeofday","setdatetime ו-timeofday","בשלב הנוכחי הוחלט שלא למפות את medicationstates/medicationstate/@setdatetime ל־dosageinstruction.timing.repeat.timeofday. ערך setdatetime מייצג זמן שינוי סטטוס במערכת cato, כגון planned, order approved או physician verified, ואינו מייצג בהכרח את שעת המתן המתוכננת למטופל. לכן הוא לא ישמש לתיאור תזמון המינון. מועד המתן המתוכנן ימופה מתוך therapy:medication/date ל־dosageinstruction.timing.event."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('9b77722a-5d0e-5e13-a700-ed938ab74a8f'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:242d8c81633271e819bd6fefaad3555af3b47d0fd4a2c641e0f791477cccd058', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.authoredon","זמן יצירת ההוראה","יש לאתר את כל מופעי medicationstate תחת therapy:medication/medicationstates שבהם @state=''physician verified''. יש לבחור את המופע בעל ערך @setdatetime המוקדם ביותר ולאכלס ערך זה ב־medicationrequest.authoredon. \nאין להשתמש באירוע planned או בסטטוסים מאוחרים יותר לצורך קביעת authoredon."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.authoredon","זמן יצירת ההוראה","יש לאתר את כל מופעי medicationstate תחת therapy:medication/medicationstates שבהם @state=''physician verified''. יש לבחור את המופע בעל ערך @setdatetime המוקדם ביותר ולאכלס ערך זה ב־medicationrequest.authoredon. \nאין להשתמש באירוע planned או בסטטוסים מאוחרים יותר לצורך קביעת authoredon."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('dece3908-233f-59f5-84ec-cdc8c9442e6b'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:dc23ad23b9f1b6e045b6e279251d430ab7855fb4ae607c9d1c12b76b00c3446d', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.extension[sub-dosage-step","sub-dosage-step","בשלב הנוכחי הוחלט שלא למפות את ext-sub-dosage-step עבור הוראות המגיעות מ-cato. בקבצי ה-xml שנבדקו לא נמצא מקור מובנה לשלבי מינון פנימיים הכוללים מספר שלב, מינון, קצב, נפח או משך לכל שלב. \nמרווחים בין מחזורים וימי טיפול בתוך מחזור אינם נחשבים sub-dosage-step, אלא מידע מהפרוטוקול או תזמון מתן. הוראות קליניות המופיעות כטקסט חופשי, כגון העלאת קצב הדרגתית, יישמרו כטקסט תחת dosageinstruction.text או dosageinstruction.additionalinstruction ולא יפורקו אוטומטית לשלבים מובנים."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.extension[sub-dosage-step","sub-dosage-step","בשלב הנוכחי הוחלט שלא למפות את ext-sub-dosage-step עבור הוראות המגיעות מ-cato. בקבצי ה-xml שנבדקו לא נמצא מקור מובנה לשלבי מינון פנימיים הכוללים מספר שלב, מינון, קצב, נפח או משך לכל שלב. \nמרווחים בין מחזורים וימי טיפול בתוך מחזור אינם נחשבים sub-dosage-step, אלא מידע מהפרוטוקול או תזמון מתן. הוראות קליניות המופיעות כטקסט חופשי, כגון העלאת קצב הדרגתית, יישמרו כטקסט תחת dosageinstruction.text או dosageinstruction.additionalinstruction ולא יפורקו אוטומטית לשלבים מובנים."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('7b23c612-240d-5fe0-b76d-2a837fa7ba5b'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:75401d6bd1422988a766d27ecb1258ac9fe81bcef4fba9d17a5872f01fbdf8be', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.route","route וקידוד סטנדרטי","מיפוי route מ־cato לקוד סטנדרטי יתבצע רק באמצעות טבלת המרה מאושרת, כגון cato routename → snomed ct route code. אין למפות ערך טקסטואלי כגון i.v. ישירות לקוד snomed ללא lookup מאושר. \nערך routename המקורי מ־cato ייוצג באמצעות הקידוד המקומי ב־route.coding[internal]. \nהשאלה האם לאכלס בנוסף גם route.text עדיין פתוחה להחלטת הצוות. כאשר קיימת התאמה מאושרת, יתווסף גם קידוד snomed ct."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.route","route וקידוד סטנדרטי","מיפוי route מ־cato לקוד סטנדרטי יתבצע רק באמצעות טבלת המרה מאושרת, כגון cato routename → snomed ct route code. אין למפות ערך טקסטואלי כגון i.v. ישירות לקוד snomed ללא lookup מאושר. \nערך routename המקורי מ־cato ייוצג באמצעות הקידוד המקומי ב־route.coding[internal]. \nהשאלה האם לאכלס בנוסף גם route.text עדיין פתוחה להחלטת הצוות. כאשר קיימת התאמה מאושרת, יתווסף גם קידוד snomed ct."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('11560d21-a57d-53b2-8c50-d6bbb730c07e'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:f2f2c0bf1de2fdd0b862b886b1a5b3d7ffe456521bf6f1a1cef4785e50780571', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","extension[medication-regimen]","medication-regimen","ה־extension medication regimen משמש לייצוג מידע ברמת תוכנית הטיפול האונקולוגי. יש לאכלס רק תתי־אלמנטים שעבורם קיים מקור אמין ב־cato או שניתן לגזור אותם באופן חד־משמעי מהמידע הקיים.\n\nה־slice activeingredient מוגדר בפרופיל בקרדינליות 0..1 בלבד. לכן כאשר therapy:medication כולל prescribeddrug יחיד ניתן לייצג את החומר הפעיל באמצעות activeingredient. כאשר קיימים מספר מופעי prescribeddrug תחת אותו therapy:medication, כלומר ההוראה כוללת יותר מחומר גנרי אחד, אין ליצור מספר מופעי activeingredient ואין לבחור אחד מהחומרים באופן שרירותי.\n\nבתרחיש של מספר חומרים גנריים, החומרים הפעילים ייוצגו באמצעות medication.ingredient[]. כלל זה מתייחס למבנה ההוראה ב־cato ואינו תלוי באופן שבו משאב medication מיוצג ב־fhir, בין אם כ־contained ובין אם כ־referenced.\n\nאין להשתמש ב־activeingredient לצורך ייצוג מספר חומרים פעילים כאשר מקור cato כולל מספר prescribeddrug, ויש לשמור על הפרדה בין מידע ברמת medicationrequest לבין פירוט המרכיבים ברמת medication."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["extension[medication-regimen]","medication-regimen","ה־extension medication regimen משמש לייצוג מידע ברמת תוכנית הטיפול האונקולוגי. יש לאכלס רק תתי־אלמנטים שעבורם קיים מקור אמין ב־cato או שניתן לגזור אותם באופן חד־משמעי מהמידע הקיים.\n\nה־slice activeingredient מוגדר בפרופיל בקרדינליות 0..1 בלבד. לכן כאשר therapy:medication כולל prescribeddrug יחיד ניתן לייצג את החומר הפעיל באמצעות activeingredient. כאשר קיימים מספר מופעי prescribeddrug תחת אותו therapy:medication, כלומר ההוראה כוללת יותר מחומר גנרי אחד, אין ליצור מספר מופעי activeingredient ואין לבחור אחד מהחומרים באופן שרירותי.\n\nבתרחיש של מספר חומרים גנריים, החומרים הפעילים ייוצגו באמצעות medication.ingredient[]. כלל זה מתייחס למבנה ההוראה ב־cato ואינו תלוי באופן שבו משאב medication מיוצג ב־fhir, בין אם כ־contained ובין אם כ־referenced.\n\nאין להשתמש ב־activeingredient לצורך ייצוג מספר חומרים פעילים כאשר מקור cato כולל מספר prescribeddrug, ויש לשמור על הפרדה בין מידע ברמת medicationrequest לבין פירוט המרכיבים ברמת medication."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('44d85ddc-290c-5253-9ea3-e6813de205de'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:a977f5b1d47f28615ad3299c9497e9f16ca5f3c4c25e4954f6d900426ed1a5f2', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.timing.repeat.offset","relativeadministrationdatetime","relativeadministrationdatetime מייצג יחס בין שתי הוראות תרופה,\n לדוגמה הוראה הניתנת 30 דקות לפני תרופה אחרת. הוחלט שלא למפות מידע זה ל־dosageinstruction.timing.repeat.offset, מאחר ש־offset ב־fhir timing אינו מיועד לתיאור תלות בין שתי הוראות תרופה שונות במודל זה. המידע יישמר בטקסט ההוראה או ייבחן בעתיד כהרחבה ייעודית."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.timing.repeat.offset","relativeadministrationdatetime","relativeadministrationdatetime מייצג יחס בין שתי הוראות תרופה,\n לדוגמה הוראה הניתנת 30 דקות לפני תרופה אחרת. הוחלט שלא למפות מידע זה ל־dosageinstruction.timing.repeat.offset, מאחר ש־offset ב־fhir timing אינו מיועד לתיאור תלות בין שתי הוראות תרופה שונות במודל זה. המידע יישמר בטקסט ההוראה או ייבחן בעתיד כהרחבה ייעודית."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('6f2d3550-dca5-53da-8bb5-9949ee15aa8b'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:f6e889b565fafa296531730c9cda9e778bb7b93a53e2aae7d9419f86bf7783b5', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medication.ingredient.strength","ייצוג של חוזק התרופה","האלמנט contained.ingredient.strength שייך למשאב medication הפנימי המופיע תחת contained, ואינו אלמנט ישיר של medicationrequest. ניתן להשתמש בו כאשר ה-contained medication מייצג תמהיל תרופה, לצורך תיאור חוזק או ריכוז המרכיב הפעיל בתוך התמהיל, לדוגמה כמות החומר הפעיל ביחס לנפח המיהול. \nעם זאת, strength אינו מחליף את dosageinstruction.doseandrate.dosequantity, שמייצג את המנה שהוזמנה למטופל. במיפוי cato, strength ימופה רק כאשר קיימים מקורות מובנים לכמות החומר ולנפח המיהול, כגון finaldose ו-mlvolume, ורק עבור רכיבים פעילים. עבור נוזל מיהול לא ימופה strength כברירת מחדל."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medication.ingredient.strength","ייצוג של חוזק התרופה","האלמנט contained.ingredient.strength שייך למשאב medication הפנימי המופיע תחת contained, ואינו אלמנט ישיר של medicationrequest. ניתן להשתמש בו כאשר ה-contained medication מייצג תמהיל תרופה, לצורך תיאור חוזק או ריכוז המרכיב הפעיל בתוך התמהיל, לדוגמה כמות החומר הפעיל ביחס לנפח המיהול. \nעם זאת, strength אינו מחליף את dosageinstruction.doseandrate.dosequantity, שמייצג את המנה שהוזמנה למטופל. במיפוי cato, strength ימופה רק כאשר קיימים מקורות מובנים לכמות החומר ולנפח המיהול, כגון finaldose ו-mlvolume, ורק עבור רכיבים פעילים. עבור נוזל מיהול לא ימופה strength כברירת מחדל."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('f2730200-deef-56c8-9daf-d7eb0fe66283'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:060a0aff6956fd9c31a4ad2a5f95f58de88409116979ec19b1ec92fe4b67afa3', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","id","מזהה ה־contained medication וה־medication uid","עבור הוראות המיוצגות באמצעות contained medication, ה־contained.id יהיה הערך הקבוע cocktail, בהתאם למודל הקיים של הוראות התרופות מקמיליון. \nמזהה ההוראה המקורי של cato (therapy:medication/uid) ימופה ל־medication.identifier.value. medicationrequest.medicationreference.reference יפנה ל־#cocktail.\nלדוגמא:\ntherapy:medication/uid = 17611"],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["id","מזהה ה־contained medication וה־medication uid","עבור הוראות המיוצגות באמצעות contained medication, ה־contained.id יהיה הערך הקבוע cocktail, בהתאם למודל הקיים של הוראות התרופות מקמיליון. \nמזהה ההוראה המקורי של cato (therapy:medication/uid) ימופה ל־medication.identifier.value. medicationrequest.medicationreference.reference יפנה ל־#cocktail.\nלדוגמא:\ntherapy:medication/uid = 17611"],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('dc72008d-83f0-5043-aa51-92de80e13084'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:76386267676e3fd85cd8129ccdb3a6601b07e1847e58037d19cc2b2b869ea0d5', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.statusreason","הסיבה לסטטוס המופיע על ההוראה","ב־cato therapy export לא זוהה מקור מידע המייצג סיבה לסטטוס ההוראה. הערכים medicationstate.state ו־medicationstate.stateshortdesc מייצגים שלבי workflow במערכת cato ואינם מייצגים סיבה לסטטוס.\n במקרה של cancelled, הסטטוס הנוכחי מיוצא באמצעות therapy:medication/status = cancelled, אך סיבת הביטול שהוזנה במערכת אינה מופיעה ב־xml שנבדק. לכן medicationrequest.statusreason לא ימופה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.statusreason","הסיבה לסטטוס המופיע על ההוראה","ב־cato therapy export לא זוהה מקור מידע המייצג סיבה לסטטוס ההוראה. הערכים medicationstate.state ו־medicationstate.stateshortdesc מייצגים שלבי workflow במערכת cato ואינם מייצגים סיבה לסטטוס.\n במקרה של cancelled, הסטטוס הנוכחי מיוצא באמצעות therapy:medication/status = cancelled, אך סיבת הביטול שהוזנה במערכת אינה מופיעה ב־xml שנבדק. לכן medicationrequest.statusreason לא ימופה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('9a5fb629-793e-570d-9dea-d4fc6487177f'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:b936b5117e3c8257b0600e07fd6cc0c1cbbccbd160d21ebb7e53935cc7742050', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.status","ייצוג של מתן חלקי","medicationrequest.status מייצג את מצב ההוראה ולא את היקף הביצוע בפועל. מידע על מתן מלא, מתן חלקי, הפסקת מתן או אי־השלמת המתן שייך ל־medicationadministration ואינו משמש לקביעת medicationrequest.status"],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.status","ייצוג של מתן חלקי","medicationrequest.status מייצג את מצב ההוראה ולא את היקף הביצוע בפועל. מידע על מתן מלא, מתן חלקי, הפסקת מתן או אי־השלמת המתן שייך ל־medicationadministration ואינו משמש לקביעת medicationrequest.status"],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('f483b575-de77-57a6-82d6-1763f8977f80'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:2bd45e36c0bcfda80e55e8017a34065b7189dadfeea6e02762a7c4cd6a08f498', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","category[il-core]","ייצוג של category","האלמנט medicationrequest.category הוגדר כאופציונלי ולא כחובה. המידע הקיים במערכת המקור אינו מאפשר בכל המרכזים הרפואיים לקבוע באופן חד-משמעי אם ההוראה שייכת למסגרת אשפוז או למסגרת אמבולטורית. \nבמרכזים רפואיים שבהם נעשה שימוש בהגדרת outpatient unit, וככל שיוכח שהגדרה זו משתקפת באופן עקבי ב-xml באמצעות הערך outpatientcare, ניתן יהיה לשקול שימוש במידע זה לצורך מיפוי האלמנט. במקרים שבהם לא קיים מקור מידע אמין וחד-משמעי, האלמנט לא יאוכלס."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["category[il-core]","ייצוג של category","האלמנט medicationrequest.category הוגדר כאופציונלי ולא כחובה. המידע הקיים במערכת המקור אינו מאפשר בכל המרכזים הרפואיים לקבוע באופן חד-משמעי אם ההוראה שייכת למסגרת אשפוז או למסגרת אמבולטורית. \nבמרכזים רפואיים שבהם נעשה שימוש בהגדרת outpatient unit, וככל שיוכח שהגדרה זו משתקפת באופן עקבי ב-xml באמצעות הערך outpatientcare, ניתן יהיה לשקול שימוש במידע זה לצורך מיפוי האלמנט. במקרים שבהם לא קיים מקור מידע אמין וחד-משמעי, האלמנט לא יאוכלס."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('5bf24a5a-54a9-53d4-a23a-28ddf8de022f'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:b6ca0daa8ebd9e0cde05ab3169d73ddfbc4e8574a1250b98f91c31058e284225', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationdoseform extension","מייצג את צורת המינון (dose form) של התרופה לצורך תיאור האופן הפיזי שבו התרופה מסופקת או ניתנת לדוגמא :\ncapsule","הוחלט שלא למפות את הרחבת medicationdoseform. ב־cato therapy xml לא קיים מקור מובנה, עקבי וחד־משמעי לצורת המינון עבור כלל ההוראות.\n dosageformuid, כאשר קיים, עשוי לכלול ערך תיאורי משולב ואינו מופיע בכל התרופות. containertype מייצג מיכל ולא dose form ולכן אינו מקור מתאים. מאחר שה־extension אינו חובה בפרופיל, אין לבצע parsing או inference מתוך טקסט, דרך מתן או סוג מיכל."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationdoseform extension","מייצג את צורת המינון (dose form) של התרופה לצורך תיאור האופן הפיזי שבו התרופה מסופקת או ניתנת לדוגמא :\ncapsule","הוחלט שלא למפות את הרחבת medicationdoseform. ב־cato therapy xml לא קיים מקור מובנה, עקבי וחד־משמעי לצורת המינון עבור כלל ההוראות.\n dosageformuid, כאשר קיים, עשוי לכלול ערך תיאורי משולב ואינו מופיע בכל התרופות. containertype מייצג מיכל ולא dose form ולכן אינו מקור מתאים. מאחר שה־extension אינו חובה בפרופיל, אין לבצע parsing או inference מתוך טקסט, דרך מתן או סוג מיכל."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('00980a9d-1471-5679-b958-94869cae0c0c'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:5f018b8c40b1730975eb2d05112094f31e0960813cb1d0aee90b478b3fb35a50', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.encounter","ייצוג של medicationrequest.encounter","ב־cato therapy export לא קיים מקור מידע המאפשר לקשר באופן אמין את הוראת התרופה ל־fhir encounter. למרות שתוכנית הטיפול ב־cato נוצרת מתוך הקשר קליני ב־chameleon, מזהה ה־medicalrecord אינו נכלל ב־xml המשמש ליצירת משאב ה־medicationrequest. \nהוחלט שלא לבצע enrichment חיצוני או lookup מול chameleon לצורך השלמת medicationrequest.encounter. עבור medicationrequest שמקורו ב־cato יוגדר פרופיל dgmc מתאים שבו encounter אינו אלמנט חובה, ולכן medicationrequest.encounter לא יאוכלס."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.encounter","ייצוג של medicationrequest.encounter","ב־cato therapy export לא קיים מקור מידע המאפשר לקשר באופן אמין את הוראת התרופה ל־fhir encounter. למרות שתוכנית הטיפול ב־cato נוצרת מתוך הקשר קליני ב־chameleon, מזהה ה־medicalrecord אינו נכלל ב־xml המשמש ליצירת משאב ה־medicationrequest. \nהוחלט שלא לבצע enrichment חיצוני או lookup מול chameleon לצורך השלמת medicationrequest.encounter. עבור medicationrequest שמקורו ב־cato יוגדר פרופיל dgmc מתאים שבו encounter אינו אלמנט חובה, ולכן medicationrequest.encounter לא יאוכלס."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('4df6e924-538b-508b-802c-76daabcb6d58'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:914cfa7672b1e5fc88884ece5ea44fb6b6a1538c13a19465d8da7959a116bd29', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.courseoftherapytype","ייצוג של courseoftherapytype","medicationrequest.courseoftherapytype הוא אלמנט חובה בפרופיל. ב־cato לא קיים שדה ישיר המייצג את סוג מהלך הטיפול, והערכים הקיימים ב־valueset אינם מייצגים באופן מדויק טיפול אונקולוגי מחזורי מבוסס פרוטוקול. לאחר בחינת הערכים הקיימים הוחלט שלא להשתמש בערכים כגון acute, continuous, chronic, prn או seasonal כאשר הם אינם משקפים נאמנה את משמעות הטיפול. הוחלט ליצור או להרחיב valueset כך שיכלול ערכים המתאימים לטיפול אונקולוגי מחזורי ולטיפול אונקולוגי חד־מחזורי. הערך ב־courseoftherapytype ייקבע בהתאם לסוג תוכנית הטיפול ב־cato ולכללי הסיווג שיאושרו עבור ה־valueset."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.courseoftherapytype","ייצוג של courseoftherapytype","medicationrequest.courseoftherapytype הוא אלמנט חובה בפרופיל. ב־cato לא קיים שדה ישיר המייצג את סוג מהלך הטיפול, והערכים הקיימים ב־valueset אינם מייצגים באופן מדויק טיפול אונקולוגי מחזורי מבוסס פרוטוקול. לאחר בחינת הערכים הקיימים הוחלט שלא להשתמש בערכים כגון acute, continuous, chronic, prn או seasonal כאשר הם אינם משקפים נאמנה את משמעות הטיפול. הוחלט ליצור או להרחיב valueset כך שיכלול ערכים המתאימים לטיפול אונקולוגי מחזורי ולטיפול אונקולוגי חד־מחזורי. הערך ב־courseoftherapytype ייקבע בהתאם לסוג תוכנית הטיפול ב־cato ולכללי הסיווג שיאושרו עבור ה־valueset."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('0ccfeadb-c5a3-5be4-94a1-ace548fd4a7f'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:113034d29639ef232f10dec7b4607122b9c58efeae00a8e72f39204161d010be', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.supportinginformation:bodyweight","ייצוג של משקל / שטח גוף","מידע אודות משקל המטופל קיים ב- cato xml תחת medicalresults עם זאת, לא קיים קשר מפורש המאפשר לקבוע כי המשקל המופיע ב- xml הוא המשקל שעל בסיסו חושבה או אושרה הוראת התרופה. \nבנוסף, בהתאם להגדרות cato עדכון משקל עשוי שלא לעבור למערכת כאשר השינוי אינו חורג מסף מוגדר, לדוגמה 10%, בעוד שהוראה קיימת עשויה להישאר ללא שינוי גם לאחר עדכון משקל. מאחר ש- supportinginformation:bodyweight אינו אלמנט חובה בפרופיל, הוחלט בשלב זה שלא למפותו, כדי להימנע מייצוג משקל שאינו בהכרח המשקל הרלוונטי להוראה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.supportinginformation:bodyweight","ייצוג של משקל / שטח גוף","מידע אודות משקל המטופל קיים ב- cato xml תחת medicalresults עם זאת, לא קיים קשר מפורש המאפשר לקבוע כי המשקל המופיע ב- xml הוא המשקל שעל בסיסו חושבה או אושרה הוראת התרופה. \nבנוסף, בהתאם להגדרות cato עדכון משקל עשוי שלא לעבור למערכת כאשר השינוי אינו חורג מסף מוגדר, לדוגמה 10%, בעוד שהוראה קיימת עשויה להישאר ללא שינוי גם לאחר עדכון משקל. מאחר ש- supportinginformation:bodyweight אינו אלמנט חובה בפרופיל, הוחלט בשלב זה שלא למפותו, כדי להימנע מייצוג משקל שאינו בהכרח המשקל הרלוונטי להוראה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('9abaf5f4-2d4e-5049-835d-1fe5641ebc33'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:449eda25ff5ad70ad69143aa56dc2f599e338d5dbe6355e3d00e4db1c3ff71e5', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.performer","ייצוג של הגורם המיועד לבצע את מתן התרופה בהתאם להוראה.","האלמנט medicationrequest.performer מוגדר בקרדינליות 0..1 ואינו must support. הסימון c מציין קיום constraint ואינו מחייב את שליחת האלמנט.\nבהוראות מקמיליון האלמנט משמש לייצוג תרופות הנלקחות עצמאית על ידי המטופל, בהתאם לאינדיקציית independent. ב-cato לא קיימת אינדיקציה מקבילה או מידע אחר המזהה באופן מפורש את הגורם המיועד לבצע את המתן.\nלכן הוחלט שלא למפות את medicationrequest.performer עבור הוראות שמקורן ב-cato."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.performer","ייצוג של הגורם המיועד לבצע את מתן התרופה בהתאם להוראה.","האלמנט medicationrequest.performer מוגדר בקרדינליות 0..1 ואינו must support. הסימון c מציין קיום constraint ואינו מחייב את שליחת האלמנט.\nבהוראות מקמיליון האלמנט משמש לייצוג תרופות הנלקחות עצמאית על ידי המטופל, בהתאם לאינדיקציית independent. ב-cato לא קיימת אינדיקציה מקבילה או מידע אחר המזהה באופן מפורש את הגורם המיועד לבצע את המתן.\nלכן הוחלט שלא למפות את medicationrequest.performer עבור הוראות שמקורן ב-cato."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('26eb25f6-0bcc-5ce5-b720-c615b8956de9'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:2d6a04a76609f7e1718876d90d93e432349c9cb5d487e23035c88ba8984cc797', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.requester","ייצוג של הרופא שאישר רפואית את הוראת התרופה במערכת cato באמצעות מעבר התרופה לסטטוס physician verified. רק תרופה שעברה סטטוס זה נחשבת להוראה רפואית פעילה המיועדת ליצירה כ־medicationrequest","בהתאם למידול הקיים של הוראות תרופה ממערכת קמיליון, עבור medicationrequest.requester ייוצג רק requester.reference. תתי־האלמנטים requester.type, requester.identifier ו־requester.display לא ימופו.\nמקור המידע הוא רשומת medicationstate ברמת התרופה שבה state=\"physician verified\". יש לשלוף את useruid של המשתמש החתום על סטטוס זה, לבצע התאמה ל־practitioner המתאים ולאכלס את requester.reference.\nמאחר שרק תרופה שעברה physician verified נחשבת להוראה רפואית פעילה, כל medicationrequest פעיל צפוי לכלול רופא מאשר שניתן לקשרו ל־practitioner."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.requester","ייצוג של הרופא שאישר רפואית את הוראת התרופה במערכת cato באמצעות מעבר התרופה לסטטוס physician verified. רק תרופה שעברה סטטוס זה נחשבת להוראה רפואית פעילה המיועדת ליצירה כ־medicationrequest","בהתאם למידול הקיים של הוראות תרופה ממערכת קמיליון, עבור medicationrequest.requester ייוצג רק requester.reference. תתי־האלמנטים requester.type, requester.identifier ו־requester.display לא ימופו.\nמקור המידע הוא רשומת medicationstate ברמת התרופה שבה state=\"physician verified\". יש לשלוף את useruid של המשתמש החתום על סטטוס זה, לבצע התאמה ל־practitioner המתאים ולאכלס את requester.reference.\nמאחר שרק תרופה שעברה physician verified נחשבת להוראה רפואית פעילה, כל medicationrequest פעיל צפוי לכלול רופא מאשר שניתן לקשרו ל־practitioner."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('9cc47fe7-3d44-5786-97cf-83c3b036510f'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:0b7506615a8b730db891c06637d4e3e7205a8c05a18f2472b7bab67e44c135c1', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.recorder","הגורם שתיעד או הזין את ההוראה בשם הגורם שנתן את ההוראה , לדוגמא במקרה של הוראה טלפונית","האלמנט אינו חובה בפרופיל dgmc. בקמיליון נעשה בו שימוש לייצוג הגורם שהזין הוראה טלפונית בשם הרופא. \nב-cato xml לא זוהתה אינדיקציה מקבילה או מקור מידע חד-משמעי ל-recorder, ולכן הוחלט שלא לכלול את האלמנט במידול."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.recorder","הגורם שתיעד או הזין את ההוראה בשם הגורם שנתן את ההוראה , לדוגמא במקרה של הוראה טלפונית","האלמנט אינו חובה בפרופיל dgmc. בקמיליון נעשה בו שימוש לייצוג הגורם שהזין הוראה טלפונית בשם הרופא. \nב-cato xml לא זוהתה אינדיקציה מקבילה או מקור מידע חד-משמעי ל-recorder, ולכן הוחלט שלא לכלול את האלמנט במידול."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('1b093ba2-516b-5f24-b89d-2fa8cf3a3fa5'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:cb76822429d14c575b87a501fed47ce34ecbec41c3ea927416dbbb67cf55226b', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.basedon","מייצג את תוכנית הטיפול או מחזור הטיפול של cato","האלמנט basedon מיועד לקישור הוראת התרופה ל resource אחר שעל בסיסו נוצרה ההוראה. ב cato קיימת היררכיה של therapy -> cycle -> medication וכן מזהים כגון catotherapyid ו-cycleid, אך מזהים אלו הם מזהים פנימיים של cato ואינם מהווים reference למשאב fhir. \nבמסגרת המידול הנוכחי לא נוצר resource נפרד המייצג את תוכנית הטיפול או מחזור הטיפול של cato, ולכן אין מקור מתאים למיפוי basedon. הוחלט שלא למפות את האלמנט במסגרת המידול הנוכחי. אם בעתיד תמודל הcato - therapy כמשאב fhir מתאים, לדוגמה careplan, ניתן יהיה לבחון קישור אליו באמצעות medicationrequest.basedon ."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.basedon","מייצג את תוכנית הטיפול או מחזור הטיפול של cato","האלמנט basedon מיועד לקישור הוראת התרופה ל resource אחר שעל בסיסו נוצרה ההוראה. ב cato קיימת היררכיה של therapy -> cycle -> medication וכן מזהים כגון catotherapyid ו-cycleid, אך מזהים אלו הם מזהים פנימיים של cato ואינם מהווים reference למשאב fhir. \nבמסגרת המידול הנוכחי לא נוצר resource נפרד המייצג את תוכנית הטיפול או מחזור הטיפול של cato, ולכן אין מקור מתאים למיפוי basedon. הוחלט שלא למפות את האלמנט במסגרת המידול הנוכחי. אם בעתיד תמודל הcato - therapy כמשאב fhir מתאים, לדוגמה careplan, ניתן יהיה לבחון קישור אליו באמצעות medicationrequest.basedon ."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('d05b030b-5d42-53ac-b279-e3512ac85da2'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:f0f4a12a2d365b96c7bc8c7211c196f70b4af66a2b763a59c5f3d1fa12916bc7', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.groupidentifier","קבוצת הוראות שנוצרו או אושרו יחד","ב־cato לא זוהה מזהה המייצג באופן חד־משמעי קבוצת הוראות שנוצרו או אושרו יחד. cycleid מייצג מחזור טיפול ואינו שקול ל־medicationrequest.groupidentifier, מאחר שניתן להוסיף תרופות לאותו מחזור גם במועדים שונים. \nמאחר שהאלמנט אינו חובה בפרופיל, הוחלט שלא למפות את medicationrequest.groupidentifier עבור הוראות המגיעות מ־cato."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.groupidentifier","קבוצת הוראות שנוצרו או אושרו יחד","ב־cato לא זוהה מזהה המייצג באופן חד־משמעי קבוצת הוראות שנוצרו או אושרו יחד. cycleid מייצג מחזור טיפול ואינו שקול ל־medicationrequest.groupidentifier, מאחר שניתן להוסיף תרופות לאותו מחזור גם במועדים שונים. \nמאחר שהאלמנט אינו חובה בפרופיל, הוחלט שלא למפות את medicationrequest.groupidentifier עבור הוראות המגיעות מ־cato."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('4f139154-7fa4-5090-807f-d67ad41c7c51'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:5a6ea5112f9fb26aa147ef574e538a894e842182d3b6b3f98784b49a9c674a8d', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.additionalinstruction","מידע לגבי אופן הכנת התרופה לדוגמא :\n allow to dissolve under the tongue. do not transfer from this container. keep tightly closed. discard eight weeks after opening","לא נמצא ב־cato xml מידע מובנה התואם ל־additional dosage instructions.\n ההערות commentsshownbeforemed ו־commentsshownaftermed הן טקסט חופשי ואינן מייצגות בהכרח את המשמעות הטרמינולוגית של האלמנט, ולכן אינן ממופות אליו."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.additionalinstruction","מידע לגבי אופן הכנת התרופה לדוגמא :\n allow to dissolve under the tongue. do not transfer from this container. keep tightly closed. discard eight weeks after opening","לא נמצא ב־cato xml מידע מובנה התואם ל־additional dosage instructions.\n ההערות commentsshownbeforemed ו־commentsshownaftermed הן טקסט חופשי ואינן מייצגות בהכרח את המשמעות הטרמינולוגית של האלמנט, ולכן אינן ממופות אליו."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('f8beb2f8-a915-5943-8803-1c00f60c849a'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:8c9970161f4dfe6da262afce2a0cd125e83a187c3f21e9a18963023322ca738f', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","dosageinstruction.patientinstruction","הנחיות המיעדות למטופל לגבי ההוראה","לא נמצא ב־cato xml שדה ייעודי להנחיות המיועדות למטופל. הערות התרופה הקיימות ב־xml אינן מזוהות כהנחיות למטופל ולכן האלמנט אינו ממופה."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["dosageinstruction.patientinstruction","הנחיות המיעדות למטופל לגבי ההוראה","לא נמצא ב־cato xml שדה ייעודי להנחיות המיועדות למטופל. הערות התרופה הקיימות ב־xml אינן מזוהות כהנחיות למטופל ולכן האלמנט אינו ממופה."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz),
  ('48241b6a-a5b2-562d-8cd2-d484390e52dc'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:6e14ad6e8c625a8b0ecf0785055760a0676d3f762523765c12f16945b14be484', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","medicationrequest.note","הערות ברמת הוראה לתרופה","עבור כל אחד מהאלמנטים therapy:medication/commentsshownbeforemed, therapy:medication/commentsshownwithmed ו־therapy:medication/commentsshownaftermed, אם האלמנט קיים וערכו אינו null או ריק, יש ליצור מופע נפרד במערך medicationrequest.note[]. יש לאכלס את note.text באופן הבא:\n commentsshownbeforemed → שרשור \"before medication: \" לערך המקור; commentsshownwithmed → שרשור \"with medication: \" לערך המקור; commentsshownaftermed → שרשור \"after medication: \" לערך המקור. אם אלמנט המקור אינו קיים או ריק, אין ליצור עבורו מופע note[]. יש לשמור את תוכן ההערה המקורי ללא שינוי, למעט הוספת הקידומת"],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["medicationrequest.note","הערות ברמת הוראה לתרופה","עבור כל אחד מהאלמנטים therapy:medication/commentsshownbeforemed, therapy:medication/commentsshownwithmed ו־therapy:medication/commentsshownaftermed, אם האלמנט קיים וערכו אינו null או ריק, יש ליצור מופע נפרד במערך medicationrequest.note[]. יש לאכלס את note.text באופן הבא:\n commentsshownbeforemed → שרשור \"before medication: \" לערך המקור; commentsshownwithmed → שרשור \"with medication: \" לערך המקור; commentsshownaftermed → שרשור \"after medication: \" לערך המקור. אם אלמנט המקור אינו קיים או ריק, אין ליצור עבורו מופע note[]. יש לשמור את תוכן ההערה המקורי ללא שינוי, למעט הוספת הקידומת"],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::ti