  ('781d992e-9556-57d2-b081-288f15bb0f0e'::uuid, (select reference_value_id from pg_temp.bl001_ref where domain_code='MAPPING_KIND' and value_code='GOVERNANCE_GUIDANCE' and version_number=1), 'CATO', 'MedicationRequest', 'v1', 'me:v1:c6af4d63e477db594d12e214ef3c1473136bdacf2360957a2e1aa5fb351fb270', '{"canonical_tuple":["GOVERNANCE_GUIDANCE","cato","medicationrequest","global_mapping_policy","no_source_no_inference_and_choice_handling","ext-medication-regimen","הרחבה של תוכנית הטיפול","יש למפות ב־ext-medication-regimen רק מידע שקיים או ניתן לגזור באופן מהימן מ־cato: protocolname, totalcycles, currentcyclenumber ו־activeingredient.text.\ntotalcycles ייקבע לפי מספר מופעי therapy:cycle הקיימים בזמן הייצוא.\ncurrentcyclenumber ייקבע על־ידי חילוץ המספר הסידורי מתוך therapy:cycle/name של המחזור המכיל את הוראת התרופה. בדיקה מול xml לפני ואחרי מחיקת מחזור באמצע התוכנית הראתה כי cato מבצע renumbering של cycle/name, בעוד cycleid נשמר; לכן אין להשתמש ב־cycleid לצורך מיפוי זה.\nactiveingredientreference עדיין wip.\nאין למפות text, durationbetweencycles ו־cumulativeactiveingredient."],"decision_topic_code":"NO_SOURCE_NO_INFERENCE_AND_CHOICE_HANDLING","fhir_resource":"MedicationRequest","governed_guidance_identity":["ext-medication-regimen","הרחבה של תוכנית הטיפול","יש למפות ב־ext-medication-regimen רק מידע שקיים או ניתן לגזור באופן מהימן מ־cato: protocolname, totalcycles, currentcyclenumber ו־activeingredient.text.\ntotalcycles ייקבע לפי מספר מופעי therapy:cycle הקיימים בזמן הייצוא.\ncurrentcyclenumber ייקבע על־ידי חילוץ המספר הסידורי מתוך therapy:cycle/name של המחזור המכיל את הוראת התרופה. בדיקה מול xml לפני ואחרי מחיקת מחזור באמצע התוכנית הראתה כי cato מבצע renumbering של cycle/name, בעוד cycleid נשמר; לכן אין להשתמש ב־cycleid לצורך מיפוי זה.\nactiveingredientreference עדיין wip.\nאין למפות text, durationbetweencycles ו־cumulativeactiveingredient."],"guidance_scope":"GLOBAL_MAPPING_POLICY","mapping_kind":"GOVERNANCE_GUIDANCE","source_system":"CATO"}'::jsonb, '2026-09-24T21:08:29Z'::timestamptz);
