  ('94d436b3-537d-5092-905b-8e6b9a4ad51a'::uuid, 'dosageInstruction.route.coding[internal]', 'CATO', 'XML', 'CATO Therapy Export', 'Therapy:Medication/DataTypes:ApplicationInfo/@RouteName', 'IL CORE', NULL, 'יש ליצור coding פנימי מערך RouteName.', 'הקידוד המקומי של דרך המתן כפי שהיא מוגדרת ב־CATO.', '0..*', 0, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL),
  ('98f9425c-60ac-53e2-aba7-201ee369071f'::uuid, 'dosageInstruction.route.coding[internal].system', 'x', 'Fixed Value', 'x', NULL, 'IL CORE', 'http://fhir.<hospital-name>.health.gov.il/cs/cato-med-route', NULL, 'מערכת הקידוד המקומית המשמשת לייצוג דרכי מתן מ־CATO.', '0..1', 0, 1, false, NULL, NULL, NULL, NULL, NULL, NULL),
  ('9637d507-9f42-5e97-907e-09c8d4c9633e'::uuid, 'dosageInstruction.route.coding[internal].code', 'CATO', 'XML', 'CATO Therapy Export', 'ApplicationInfo/@RouteName', 'IL CORE', NULL, 'העבר את ערך RouteName כקוד מקומי ללא שינוי, לדוגמה i.v.', 'קוד דרך המתן המקומי כפי שנשמר ב-CATO.', '0..1', 0, 1, false, NULL, NULL, NULL, 'i.v', NULL, NULL),
  ('c325ab14-843a-52d8-b717-0efb54715442'::uuid, 'dosageInstruction.route.coding[internal].display', 'CATO', 'XML', 'CATO Therapy Export', 'ApplicationInfo/@RouteName', 'IL CORE', NULL, 'העבר את ערך RouteName כ-display של הקידוד המקומי.', 'תיאור דרך המתן המקומית כפי שנשמר ב-CATO.', '0..1', 0, 1, false, NULL, NULL, NULL, 'i.v', NULL, NULL),
  ('4bff6a07-300a-542f-9105-f6a2afaf47d2'::uuid, 'dosageInstruction.route.coding[snomed]', NULL, NULL, NULL, NULL, 'IL CORE', NULL, NULL, 'ייצוג דרך המתן באמצעות קוד SNOMED CT תקני.', '0..*', 0, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL),
  ('64a51fc2-2f13-5731-8f26-523e193f46f0'::uuid, 'dosageInstruction.route.coding[snomed].system', 'x', 'Fixed Value', 'X', 'X', 'IL CORE', 'http://snomed.info/sct', 'בצע lookup מטבלת המרה מאושרת CATO RouteName → SNOMED CT.
insert into s2t_fhir.element_mapping (mapping_record_id, target_fhir_path, source_system_raw, interface_type, interface_name, source_expression, profile_context, fixed_value, transformation_rule, source_business_definition, cardinality_raw, cardinality_min, cardinality_max, cardinality_max_unbounded, valueset_binding, mandated_code_system, irrelevant_under_s2t_raw, example_value, exception_handling, notes) values
  ('c79db813-c7dd-50d3-9c8a-3323f076cced'::uuid, 'dosageInstruction.maxDosePerPeriod.denominator.system', NULL, NULL, NULL, NULL, 'IL CORE', NULL, NULL, NULL, '0..1', 0, 1, false, NULL, NULL, NULL, NULL, NULL, NULL),
  ('9c9dddd3-81e8-5ffd-908f-bdbad274c020'::uuid, 'dosageInstruction.maxDosePerPeriod.denominator.code', NULL, NULL, NULL, NULL, 'IL CORE', NULL, NULL, NULL, '0..1', 0, 1, false, NULL, NULL, NULL, NULL, NULL, NULL),
  ('9254038f-0636-59ed-b8e5-3d460588d468'::uuid, 'extension[medication-regimen]', NULL, NULL, NULL, NULL, 'Ext: Medication Regimen HDP', NULL, 'יש ליצור מופע אחד של extension[medication-regimen] עבור MedicationRequest כאשר קיים לפחות אחד מתתי־האלמנטים שאושרו למיפוי מתוך CATO. אין ליצור את ה־extension כאשר אף אחד מתתי־האלמנטים המאושרים אינו ניתן לאכלוס.', 'מידע המתאר את הקשר של הוראת התרופה למשטר הטיפול האונקולוגי, לרבות פרוטוקול, מחזור הטיפול ומידע מצטבר רלוונטי.', '0..1', 0, 1, false, NULL, NULL, NULL, NULL, NULL, 'ה־extension מייצג מידע ברמת תוכנית הטיפול האונקולוגי. האכלוס בפועל תלוי בתתי־האלמנטים שאושרו למיפוי. אין ליצור slices שלא אושרו או שאין עבורם מקור אמין ב־CATO.'),
  ('4b6c8a4b-360d-5cef-8add-fe441660f54b'::uuid, 'extension[medication-regimen].url', 'CATO', 'XML', 'Fixed Value', NULL, 'Ext: Medication Regimen HDP', 'http://fhir.health.gov.il/StructureDefinition/ext-medication-regimen', 'כאשר נוצר extension[medication-regimen], יש לאכלס את extension[medication-regimen].url בערך הקבוע http://fhir.health.gov.il/StructureDefinition/ext-medication-regimen.', 'כתובת ה־canonical URL המזהה את ה־Medication Regimen extension.', '1..1', 1, 1, false, NULL, NULL, NULL, NULL, NULL, 'ערך קבוע. יש לאכלס אותו בכל פעם שנוצר מופע של extension[medication-regimen].'),
  ('162f8c1e-953f-5250-a915-8afd0701c4be'::uuid, 'extension[medication-regimen].extension[protocolName].valueString', 'CATO', 'XML', 'CATO Therapy Export', '/Therapy:Therapy/ProtocolName', 'Ext: Medication Regimen HDP', NULL, 'יש לקחת את הערך של ProtocolName ברמת ה־Therapy ולהעבירו ללא שינוי ל־extension[medication-regimen].extension[protocolName].valueString. 
insert into s2t_fhir.status_mapping_rule (mapping_record_id, source_status_value, target_fhir_path, target_status_value, source_sequence, source_business_definition, related_resource_note, transformation_rule, mapping_evidence_status_raw, notes) values
  ('fd1c1e63-aade-5635-b8f6-724f7eb6bb2d'::uuid, 'PLANNED', 'MedicationRequest.status', 'draft', NULL, 'נוצר, ממתין לאישור רופא', '—', 'כל ה-XML בדוגמה הוא PLANNED. אין תוקף קליני עדיין.', 'ממופה', 'לא רלוונטי'),
  ('252f59ba-6ec0-5d61-8ef8-ffb9ecbd36bb'::uuid, 'PHYSVERIFIED', 'MedicationRequest.status', 'active', NULL, 'רופא אישר — הוראה תקפה', '—', 'ה-trigger הקליני. מכאן ואילך intent=order.', 'ממופה', NULL),
  ('acf374d9-533f-5e77-8141-349a9c7d42c7'::uuid, 'PHARMVERIFIED', 'MedicationRequest.status', 'active', NULL, 'רוקח אישר את ההזמנה', '—', 'אישור פרמצבטי — ההוראה ממשיכה active.', 'ממופה', NULL),
  ('b3ebcab6-1ab5-5968-aed5-6d02d6d5445c'::uuid, 'UNDER PREPARATION', 'MedicationRequest.status', 'active', NULL, 'התרופה בהכנה פיזית בפרמצבטיקה', '—', 'ניתן לייצג ב-extension[preparationStatus] LOCAL אם נדרש מעקב הכנה.', 'ממופה', 'לא רלוונטי'),
  ('7bdc74a2-f9a2-5208-8cf8-3941e94e20ac'::uuid, 'PREPARED', 'MedicationRequest.status', 'active', NULL, 'הכנה הושלמה, מוכן למסירה', '—', 'שלב ביניים בין UNDER PREPARATION ל-DELIVERED. MedicationRequest נשאר active.', 'ממופה', NULL),
  ('47019701-f9d9-532b-ad4f-85cff1b1aa65'::uuid, 'DELIVERED', 'MedicationRequest.status', 'active', NULL, 'נמסר למחלקה / לאחות', '—', 'טרם ניתן למטופל — MedicationRequest נשאר active.', 'ממופה', 'לא רלוונטי'),
  ('69f1df67-68b9-508c-ba35-5a4d1fe082dc'::uuid, 'ADMINISTERED', 'MedicationRequest.status', 'completed', NULL, 'ניתן למטופל בפועל', '→ MedicationAdministration', 'MedicationRequest→completed. יצור MedicationAdministration עם request reference.', 'ממופה', NULL),
  ('b1596b4f-c3f8-5162-ab2f-235c2e6f4ab5'::uuid, 'CANCELLED', 'MedicationRequest.status', 'cancelled', NULL, 'בוטל', '—', 'כאשר Therapy:Medication/Status = CANCELLED, יש לבדוק את MedicationStates. אם לא קיים MedicationState שבו State = "Physician Verified", ההוראה אינה נכללת באוכלוסיית המיפוי ואין ליצור עבורה MedicationRequest. אם קיים לפחות מופע אחד של MedicationState שבו State = "Physician Verified", יש ליצור MedicationRequest עם status = cancelled ו־intent = order.', 'ממופה', NULL),
  ('f45a8e54-d394-59fc-8972-0fc33507ddf9'::uuid, 'ON HOLD', 'MedicationRequest.status', 'on-hold', NULL, 'מושהה זמנית', '—', 'סטטוס ON HOLD אינו קיים ב-CATO ולכן אינו ממופה ל-MedicationRequest.status.', 'הוחלט לא למפות', 'לא רלוונטי');
